%% ===================== Userfcn: robust constraints + loss cost =====================
function om = userfcn_most_add_robust_and_loss(om, mdi, mpopt)
    define_constants;

    % Access base case used inside MOST
    mpc0 = mdi.mpc;

    % Ensure RATE_A not pathological
    rateA = mpc0.branch(:, RATE_A);
    if all(rateA == 0)
        mpc0.branch(:, RATE_A) = 250;
    else
        mpc0.branch(rateA == 0, RATE_A) = 1e4;
    end

    % Uncertainty set parameters (from workspace via mdi or re-define here)
    % Store in mdi if you want them configurable; here we hard-code to match the specification.
    unc_buses_ext = [5; 9];
    Delta_MW      = [30; 20];

    % Loss proxy parameters
    alpha_loss = 10;
    B00_loss = 1.0;

    % Convert to internal indexing for PTDF computation
    mpc_i = ext2int(mpc0);
    baseMVA = mpc_i.baseMVA;
    bus = mpc_i.bus;
    branch = mpc_i.branch;
    gen = mpc_i.gen;

    nb = size(bus, 1);
    nl = size(branch, 1);
    ng = size(gen, 1);

    PTDF = makePTDF(baseMVA, bus, branch);      % nl x nb
    Cg = sparse(gen(:, GEN_BUS), (1:ng)', 1, nb, ng);

    % Map external uncertainty buses to internal indices
    tmp = ext2int(loadcase(mpc0));
    unc_buses_int = zeros(size(unc_buses_ext));
    for k = 1:numel(unc_buses_ext)
        bi = find(tmp.bus(:, BUS_I) == unc_buses_ext(k), 1);
        if isempty(bi)
            error('Uncertain bus ext #%d not found after ext2int.', unc_buses_ext(k));
        end
        unc_buses_int(k) = bi;
    end

    Delta_pu = Delta_MW(:) / baseMVA;
    PTDF_U = PTDF(:, unc_buses_int);
    worst = abs(PTDF_U) * Delta_pu;            % nl x 1 (p.u.)

    Fmax = branch(:, RATE_A) / baseMVA;        % p.u.

    % MOST multi-period: add constraints/costs for each time period via indexed names
    % OM in MOST is a multi-scenario/time expanded OM. We use variable sets by name.

    % Identify the time periods from mdi
    nt = mdi.idx.nt;

    % Build B_loss, B0_loss sized to ng. If no provided matrix, use small diagonal.
    % (User can replace with a calibrated B-matrix.)
    B_loss = speye(ng) * 1e-4;
    B0_loss = ones(ng, 1) * 0.0;

    % Add robust line constraints and loss cost per time period
    for t = 1:nt
        % --- Access Pd(t) in internal indexing (p.u.) ---
        % Use MOST data: fixed demand at time t is in mdi.FixedDemand(:,t) in MW
        % Fallback: use base Pd if not available.
        if isfield(mdi, 'FixedDemand') && ~isempty(mdi.FixedDemand)
            Pd_MW_t = mdi.FixedDemand(:, t);
        else
            Pd_MW_t = mpc_i.bus(:, PD);
        end
        Pd = Pd_MW_t(:) / baseMVA;

        % --- Build robust linear constraints in terms of Pg(t) ---
        % Get Pg variable indices for this time period
        % MOST names Pg variables as 'Pg' with time indexing in varsets.
        try
            vinfo = om.get_idx('var', sprintf('Pg_t%d', t)); %#ok<NASGU>
            % If a specific time-named var exists (older custom builds), use it.
            [~, idxPg] = om.get_idx('var', sprintf('Pg_t%d', t));
            i1 = idxPg.i1; iN = idxPg.iN;
        catch
            % Standard MOST: use varset 'Pg' with time dimension handled internally via stacking.
            [~, idxPg] = om.get_idx('var', 'Pg');
            % idxPg.i1 / iN refer to the full stacked vector across times; compute slice for t
            nPg = idxPg.N;
            if nPg ~= ng*nt
                error('Unexpected Pg dimension in MOST OM: got %d, expected %d.', nPg, ng*nt);
            end
            i1 = idxPg.i1 + (t-1)*ng;
            iN = i1 + ng - 1;
        end

        nv = om.getN('var');

        Arows = [];
        lvec = [];
        uvec = [];

        for ell = 1:nl
            if branch(ell, BR_STATUS) == 0
                continue;
            end
            if Fmax(ell) <= 0
                continue;
            end

            margin = Fmax(ell) - worst(ell);
            a_pg = PTDF(ell,:) * Cg;       % 1 x ng
            const = PTDF(ell,:) * (-Pd);   % scalar

            rhs_pos = margin - const;
            rhs_neg = margin + const;

            % mu_f <= margin
            Arows(end+1,:) =  a_pg; %#ok<AGROW>
            lvec(end+1,1)  = -Inf; %#ok<AGROW>
            uvec(end+1,1)  =  rhs_pos; %#ok<AGROW>

            % -mu_f <= margin
            Arows(end+1,:) = -a_pg; %#ok<AGROW>
            lvec(end+1,1)  = -Inf; %#ok<AGROW>
            uvec(end+1,1)  =  rhs_neg; %#ok<AGROW>
        end

        if ~isempty(Arows)
            A = sparse(Arows);
            Afull = sparse(size(A,1), nv);
            Afull(:, i1:iN) = A;
            cname = sprintf('ROBUST_LINE_LIMITS_BOX_t%d', t);
            om.add_lin_constraint(cname, Afull, lvec, uvec);
        end

        % --- Add quadratic loss proxy cost for Pg(t) ---
        % Cost: alpha*(Pg'B Pg + B0'Pg + B00)
        % MATPOWER quadratic cost uses (1/2)*x'Qx + c'x + k
        Q = sparse(nv, nv);
        Q(i1:iN, i1:iN) = 2 * alpha_loss * sparse(B_loss);
        c = zeros(nv, 1);
        c(i1:iN) = alpha_loss * B0_loss;
        k = alpha_loss * B00_loss;

        qname = sprintf('network_loss_cost_t%d', t);
        om.add_quad_cost(qname, Q, c, k);
    end
end

