define_constants;
clear; clc;

%% ======================== Settings ========================
casefile = 'case6ww';

% Stochastic injection bus (external bus number in case6ww)
% NOTE: if this bus does not exist in your local case6ww, change it to a valid bus number.
w_bus_ext = 6;

% Stochastic injection distribution (MW)
mu_w_MW    = 10;   % mean injection
sigma_w_MW = 5;    % std of injection

% Chance level (two-sided)
eps = 0.05;
z = norminv_approx(1 - eps/2);

% OPF options (DC) + strict violation tolerance
mpopt = mpoption('verbose', 2, 'out.all', 0, 'model', 'DC', 'opf.dc.solver', 'MIPS', 'opf.violation', 1e-6);

%% ======================== Load case ========================
mpc0 = loadcase(casefile);
mpc = mpc0;

%% ======================== Base parameter modifications ========================
% 1) Generator at bus 3, PMIN set to 0
ig = find(mpc.gen(:, GEN_BUS) == 3, 1);
if isempty(ig)
    error('No generator found at bus 3 in %s.', casefile);
end
mpc.gen(ig, PMIN) = 0;

% 2) Branch (6 -> 4), BR_B scaled by 1.1
ibr = find(mpc.branch(:, F_BUS) == 6 & mpc.branch(:, T_BUS) == 4, 1);
if isempty(ibr)
    error('Branch (6 -> 4) not found in %s.', casefile);
end
mpc.branch(ibr, BR_B) = 1.1 * mpc.branch(ibr, BR_B);

%% ======================== Data preprocessing for chance constraints ========================
% Ensure RATE_A exists and is positive; if some are 0, set them large so they don't bind
rateA = mpc.branch(:, RATE_A);
if all(rateA == 0)
    mpc.branch(:, RATE_A) = 250;       % default large value (MW-like for DC)
else
    mpc.branch(rateA == 0, RATE_A) = 1e4;
end

% Embed wind mean as negative load at the stochastic bus
bus_idx = find(mpc.bus(:, BUS_I) == w_bus_ext, 1);
if isempty(bus_idx)
    error('Stochastic injection bus %d not found in %s.', w_bus_ext, casefile);
end
mpc.bus(bus_idx, PD) = mpc.bus(bus_idx, PD) - mu_w_MW;

%% ======================== Build PTDF and chance constraints ========================
% Convert to internal indexing for PTDF and OM building
mpc_i   = ext2int(mpc);
baseMVA = mpc_i.baseMVA;
bus     = mpc_i.bus;
branch  = mpc_i.branch;
gen     = mpc_i.gen;

nb = size(bus, 1);
nl = size(branch, 1);
ng = size(gen, 1);

% PTDF (nl x nb): maps bus injections (p.u.) -> line flows (p.u.) under DC model
PTDF = makePTDF(baseMVA, bus, branch);

% Generator-to-bus incidence Cg (nb x ng)
Cg = sparse(gen(:, GEN_BUS), (1:ng)', 1, nb, ng);

% Deterministic demand Pd (p.u.) under the mean model
Pd = bus(:, PD) / baseMVA;

% Map external wind bus to internal index
% Use ext2int mapping based on mpc (with mean embedded) to be consistent
w_bus_int = find(bus(:, BUS_I) == w_bus_ext, 1);
if isempty(w_bus_int)
    error('Internal index for stochastic injection bus %d not found.', w_bus_ext);
end

sigma_w_pu = sigma_w_MW / baseMVA;
ptdf_w  = PTDF(:, w_bus_int);
sigma_f = abs(ptdf_w) * sigma_w_pu;

% Build OPF model and add chance constraints on Pg
om = opf_setup(mpc_i, mpopt);

idx = om.var.idx;
i1 = idx.i1.Pg;
iN = idx.iN.Pg;
if (iN - i1 + 1) ~= ng
    error('Pg dimension mismatch (expected %d, got %d).', ng, (iN - i1 + 1));
end
nv = om.var.N;

Fmax = branch(:, RATE_A) / baseMVA;

Arows = [];
u = [];
l = [];

for ell = 1:nl
    if branch(ell, BR_STATUS) == 0
        continue;
    end

    % mu_f(ell) = PTDF(ell,:)*(Cg*Pg - Pd)
    a_pg  = PTDF(ell, :) * Cg;      % 1 x ng
    const = PTDF(ell, :) * (-Pd);   % scalar

    margin  = Fmax(ell) - z * sigma_f(ell);
    rhs_pos = margin - const;   % for +mu_f
    rhs_neg = margin + const;   % for -mu_f

    % mu_f <= margin
    Arows(end+1, :) = a_pg;      %#ok<AGROW>
    l(end+1, 1)     = -Inf;      %#ok<AGROW>
    u(end+1, 1)     = rhs_pos;   %#ok<AGROW>

    % -mu_f <= margin
    Arows(end+1, :) = -a_pg;     %#ok<AGROW>
    l(end+1, 1)     = -Inf;      %#ok<AGROW>
    u(end+1, 1)     = rhs_neg;   %#ok<AGROW>
end

if ~isempty(Arows)
    A = sparse(Arows);                     % (#con x ng)
    Afull = sparse(size(A, 1), nv);        % (#con x nv)
    Afull(:, i1:iN) = A;
    om = om.add_lin_constraint('CHANCE_LINE_LIMITS', Afull, l, u);
end

%% ======================== Solve ========================
try
    [res_i, success, raw] = opf_execute(om, mpopt); %#ok<NASGU>
catch
    [res_i, success, raw] = opf_execute(om, mpc_i, mpopt); %#ok<NASGU>
end

res = int2ext(res_i, mpc);

if ~success
    error('Chance-constrained DCOPF failed. Try reducing sigma_w_MW / eps or increasing RATE_A.');
end

%% ======================== Post-check ========================
Pg_pu = res_i.gen(:, PG) / baseMVA;
mu_f  = PTDF * (Cg * Pg_pu - Pd);      % p.u.
lhs   = abs(mu_f) + z * sigma_f;
viol  = max(lhs - Fmax, 0);

fprintf('\n=== Chance-DCOPF summary (case6ww) ===\n');
fprintf('opf.violation = %.1e\n', 1e-6);
fprintf('eps = %.3g, z = %.6f\n', eps, z);
fprintf('Stochastic injection at bus %d: mu = %.3f MW, sigma = %.3f MW\n', w_bus_ext, mu_w_MW, sigma_w_MW);
fprintf('Objective (total cost): %.6f\n', res.f);
fprintf('Max chance line-limit violation: %.6g p.u. (%.6g MW)\n', max(viol), max(viol) * baseMVA);

%% ======================== Helper ========================
function z = norminv_approx(p)
% Compute z = Phi^{-1}(p) without requiring Statistics Toolbox.
% Phi^{-1}(p) = -sqrt(2) * erfcinv(2p)
z = -sqrt(2) * erfcinv(2*p);
end

