define_constants;

%% ===================== Load case =====================
mpc0 = loadcase('case33mg');

%% ===================== Parameter modifications =====================
% - Bus 20, BS = 0.2
% - Bus 17, VMIN = 1.0
mpc0.bus(20, BS)   = 0.2;
mpc0.bus(17, VMIN) = 1.0;

% - Branch (1->14), BR_X scale to 1.2
% - Branch (2->18), BR_R scale to 1.1
mpc0 = scale_branch_param(mpc0, 1, 14, BR_X, 1.2);
mpc0 = scale_branch_param(mpc0, 2, 18, BR_R, 1.1);

%% ===================== DCOPF options =====================
mpopt = mpoption('model', 'DC', 'verbose', 0, 'out.all', 0);
mpopt = mpoption(mpopt, 'opf.dc.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-8);

%% ===================== ATC / PTC via lambda search =====================
nb  = size(mpc0.bus, 1);
Pd0 = mpc0.bus(:, PD);

% Sink buses = all buses with positive base Pd
sink_buses = find(Pd0 > 0);

% Direction vector b_p: proportional to base Pd at sink buses
b_p = zeros(nb, 1);
b_p(sink_buses) = Pd0(sink_buses);

total_dir_load = sum(b_p(sink_buses));

fprintf('Sink buses = ['); fprintf('%d ', sink_buses); fprintf(']\n');
fprintf('Sum of direction loads (sum b_p) = %.6f MW\n', total_dir_load);

% Lambda bounds
lambda_low  = 0.0;
lambda_high = 1.0;

% Expand upper bound until infeasible
fprintf('\nExpanding lambda_high to bracket feasibility boundary...\n');
while true
    [is_feasible, ~] = check_feasibility_dcopf(mpc0, mpopt, b_p, lambda_high);
    fprintf('  lambda = %.6f -> feasible = %d\n', lambda_high, is_feasible);
    if ~is_feasible
        break;
    end
    lambda_high = lambda_high * 2;
    if lambda_high > 50
        warning('lambda_high expanded beyond 50; stopping expansion.');
        break;
    end
end

% Bisection for lambda*
tol = 1e-3;
max_iter = 40;
fprintf('\nBisection search for lambda*...\n');
for it = 1:max_iter
    lambda_mid = 0.5 * (lambda_low + lambda_high);
    [is_feasible, ~] = check_feasibility_dcopf(mpc0, mpopt, b_p, lambda_mid);
    fprintf('  iter %2d: lambda_mid = %.6f, feasible = %d\n', it, lambda_mid, is_feasible);

    if is_feasible
        lambda_low = lambda_mid;
    else
        lambda_high = lambda_mid;
    end

    if (lambda_high - lambda_low) < tol
        break;
    end
end

lambda_star = lambda_low;
ATC_MW = lambda_star * total_dir_load;

fprintf('\n================= ATC/PTC Result (DCOPF feasibility) =================\n');
fprintf('Max feasible load growth factor lambda* = %.6f\n', lambda_star);
fprintf('ATC/PTC = lambda* * sum(b_p) = %.6f MW\n', ATC_MW);
fprintf('=====================================================================\n');

%% ===================== Run final DCOPF at lambda* =====================
mpc_star = apply_lambda_and_reserve_limits(mpc0, b_p, lambda_star);
res = rundcopf(mpc_star, mpopt);

if res.success
    fprintf('\nFinal DCOPF at lambda* converged.\n');
    fprintf('Total cost: %.6f\n', res.f);

    % Print a few branch MW flows (PF)
    nprint = min(10, size(res.branch, 1));
    fprintf('Sample branch flows (from -> to, PF MW):\n');
    for k = 1:nprint
        fprintf('  %3d -> %3d : %10.6f\n', res.branch(k, F_BUS), res.branch(k, T_BUS), res.branch(k, PF));
    end
else
    fprintf('\nWARNING: Final DCOPF at lambda* did not converge/succeed.\n');
end


%% ===================== Helper functions =====================
function mpc = scale_branch_param(mpc, fbus, tbus, col, scale)
    define_constants;
    idx = find(mpc.branch(:, F_BUS) == fbus & mpc.branch(:, T_BUS) == tbus);
    if isempty(idx)
        % try reverse direction
        idx = find(mpc.branch(:, F_BUS) == tbus & mpc.branch(:, T_BUS) == fbus);
    end
    if isempty(idx)
        error('Branch (%d->%d) not found in case.', fbus, tbus);
    end
    if numel(idx) > 1
        warning('Multiple branches found for (%d,%d); scaling all matches.', fbus, tbus);
    end
    mpc.branch(idx, col) = mpc.branch(idx, col) * scale;
end

function mpc_mod = apply_lambda_and_reserve_limits(mpc0, b_p, lambda)
    define_constants;
    mpc_mod = mpc0;

    % Apply load growth: Pd(lambda) = Pd0 + lambda*b_p
    Pd0 = mpc0.bus(:, PD);
    mpc_mod.bus(:, PD) = Pd0 + lambda * b_p;

    % Reserve-consuming active power limits around base Pg0
    % Use base Pg0 from the original case as the "planned" dispatch.
    ng = size(mpc0.gen, 1);
    Pg0 = mpc0.gen(:, PG);
    PRU = 10 * ones(ng, 1);
    PRD = 10 * ones(ng, 1);

    Pmin_phys = mpc0.gen(:, PMIN);
    Pmax_phys = mpc0.gen(:, PMAX);

    Pmin_res = Pg0 - PRD;
    Pmax_res = Pg0 + PRU;

    mpc_mod.gen(:, PMIN) = max(Pmin_phys, Pmin_res);
    mpc_mod.gen(:, PMAX) = min(Pmax_phys, Pmax_res);
end

function [is_feasible, results] = check_feasibility_dcopf(mpc0, mpopt, b_p, lambda)
    mpc_mod = apply_lambda_and_reserve_limits(mpc0, b_p, lambda);
    results = rundcopf(mpc_mod, mpopt);
    is_feasible = (results.success == 1);
end

