%% ==================== Add phase angle difference penalty each period ====================
% We implement: beta * ||E*Va||^2 per period, by adding a quadratic cost on Va
% with Q = 2*beta*(E'*E) to match MATPOWER's 0.5*x'*Q*x convention.
beta = 10;
nb = size(mpc.bus, 1);
nl = size(mpc.branch, 1);
f = mpc.branch(:, F_BUS);
t = mpc.branch(:, T_BUS);

% Map external bus numbers to internal indexing 1..nb used by MOST's internal model.
% Ensure bus numbering is consecutive in internal representation.
% Use ext2int to be safe.
mpc_int = ext2int(mpc);
% rebuild f,t with internal indices
f_int = mpc_int.branch(:, F_BUS);
t_int = mpc_int.branch(:, T_BUS);
nb_int = size(mpc_int.bus, 1);

E = sparse(1:nl, f_int,  1, nl, nb_int) + sparse(1:nl, t_int, -1, nl, nb_int);
Q_va = 2 * beta * (E' * E);

% MOST provides a way to add a custom quadratic cost via the md/om structure.
% We attach it as a user-defined quadratic cost on the Va variables in each period.
%
% Approach: create a MOST user-defined cost structure for each time period.
% MOST's internal OM is created during solve, so we pass user costs via mdi.

% Initialize user-defined costs container if missing
if ~isfield(mdi, 'uc') || isempty(mdi.uc)
    mdi.uc = struct();
end

% Add quadratic cost on Va for each period.
% MOST supports uc.cost with fields: type, idx, name, N, H, Cw, fparm, cr, k, vs, etc.
% The most robust way without relying on undocumented fields is to use the
% userfcn mechanism that hooks into the OPF model after it is built.

% Define a userfcn to add quadratic cost on Va for each period
mdi.userfcn = {
    'most', 'formulation', @userfcn_most_add_angdiff_cost, struct('Qva', Q_va)
};

%% ==================== Solve with MOST ====================
mdo = most(mdi, mpopt);

%% ==================== Extract results ====================
EPg  = mdo.results.ExpectedDispatch;   % expected dispatch (multi-period)
Elam = mdo.results.GenPrices;         % LMPs / prices

most_summary(mdo);

%% ==================== User function (nested / local) ====================
function om = userfcn_most_add_angdiff_cost(om, md, mpopt, args)
% Adds quadratic cost: 0.5 * Va' * Qva * Va in each period
% where Qva = 2*beta*(E'*E), so equals beta*||E*Va||^2.

    Qva = args.Qva;

    % Determine number of periods from md
    nt = md.idx.nt;

    % Add to each time period's OPF model
    for t = 1:nt
        omt = om(t);
        % Va variable set exists in DC model
        omt = omt.add_quad_cost(sprintf('ang_diff_pen_t%03d', t), Qva, [], 0, {'Va'});
        om(t) = omt;
    end
end

