% For POLYNOMIAL cost in MATPOWER:
% gencost(row,:) = [MODEL STARTUP SHUTDOWN NCOST c(n-1) ... c0]
% COST_PARAMS_C3 refers to cubic coefficient when NCOST>=4.
% COST_PARAMS_C1 refers to linear coefficient.
