    warning('Generator at bus 8 does not use POLYNOMIAL cost model; parameter scaling may not apply as intended.');
else
    ncost = mpc.gencost(ig, NCOST);
    % Indices of coefficients within row
    % Coeffs start at column COST (5), length = ncost
    % For cubic: need ncost >= 4, coefficient order: c3 c2 c1 c0
    c_start = COST;
    if ncost >= 4
        % Scale cubic coefficient to 1 (i.e., set equal to original * 1)
        mpc.gencost(ig, c_start + (ncost-4)) = mpc.gencost(ig, c_start + (ncost-4)) * 1.0;
    else
        warning('Generator at bus 8 has NCOST < 4, cannot scale cubic coefficient (C3).');
    end
    if ncost >= 2
