mdo = most(mdi, mpopt);
if verbose
    ms = most_summary(mdo); %#ok<NASGU>
end

%% =====================
%% Local functions
%% =====================
function mdo = userfcn_formulation_additions(mdo, mpopt, args)
% Add per-period OM modifications:
%  (i) chance-constrained DC line limits via PTDF
% (ii) reactive reserve variable Qres, constraints and linear cost

define_constants;
cc   = args{1};
qres = args{2};

% MOST provides per-period OPF models in mdo.flow(t).om (for DC model)
% We loop over periods and modify each period's OM.
nt = length(mdo.flow);

for t = 1:nt
    if ~isfield(mdo.flow(t), 'om') || isempty(mdo.flow(t).om)
        continue;
    end

    om = mdo.flow(t).om;

    % Retrieve the per-period mpc (internal) if available
    if isfield(mdo.flow(t), 'mpc') && ~isempty(mdo.flow(t).mpc)
        mpc_t = mdo.flow(t).mpc;
    elseif isfield(mdo, 'mpc')
        mpc_t = mdo.mpc;
    else
        error('MOST output does not provide mpc for period %d.', t);
    end

    % Ensure internal indexing for PTDF calculations
    % (MOST/DC typically already uses internal, but enforce robustly)
    mpc_i = ext2int(mpc_t);
    baseMVA = mpc_i.baseMVA;
    bus     = mpc_i.bus;
    branch  = mpc_i.branch;
    gen     = mpc_i.gen;

    nb = size(bus, 1);
    nl = size(branch, 1);
    ng = size(gen, 1);

    % --------------------
    % (A) Chance constraints
    % --------------------
    % Ensure RATE_A exists and is nonzero; if 0, set large
    rateA = branch(:, RATE_A);
    if all(rateA == 0)
        branch(:, RATE_A) = 250;
    else
        branch(rateA == 0, RATE_A) = 1e4;
    end

    % Embed mean stochastic injection into PD at w_bus_ext as negative load
    % Determine internal bus index corresponding to external bus number
    tmp = ext2int(mpc_t);
    w_bus_int = find(tmp.bus(:, BUS_I) == cc.w_bus_ext, 1);
    if isempty(w_bus_int)
        error('Chance constraint wind bus %d not found in period %d.', cc.w_bus_ext, t);
    end

    bus(w_bus_int, PD) = bus(w_bus_int, PD) - cc.mu_w_MW;

    % PTDF and mapping
    PTDF = makePTDF(baseMVA, bus, branch);           % nl x nb
    Cg   = sparse(gen(:, GEN_BUS), (1:ng)', 1, nb, ng);
    Pd   = bus(:, PD) / baseMVA;

    sigma_w_pu = cc.sigma_w_MW / baseMVA;
    ptdf_w     = PTDF(:, w_bus_int);
    sigma_f    = abs(ptdf_w) * sigma_w_pu;

    % OM variable indexing for Pg
    idx = om.var.idx;
    nv  = om.var.N;
    i1  = idx.i1.Pg;
    iN  = idx.iN.Pg;
    if (iN - i1 + 1) ~= ng
        error('Pg dimension mismatch in period %d.', t);
    end

    Fmax = branch(:, RATE_A) / baseMVA;

    Arows = [];
    u = [];
    l = [];

    for ell = 1:nl
        if branch(ell, BR_STATUS) == 0
            continue;
        end
        a_pg  = PTDF(ell,:) * Cg;      % 1 x ng
        const = PTDF(ell,:) * (-Pd);   % scalar

        margin  = Fmax(ell) - cc.z * sigma_f(ell);
        rhs_pos = margin - const;
        rhs_neg = margin + const;

        Arows(end+1,:) = a_pg;         %#ok<AGROW>
        l(end+1,1)     = -Inf;         %#ok<AGROW>
        u(end+1,1)     = rhs_pos;      %#ok<AGROW>

        Arows(end+1,:) = -a_pg;        %#ok<AGROW>
        l(end+1,1)     = -Inf;         %#ok<AGROW>
        u(end+1,1)     = rhs_neg;      %#ok<AGROW>
    end

    if ~isempty(Arows)
        A = sparse(Arows);
        Afull = sparse(size(A,1), nv);
        Afull(:, i1:iN) = A;
        om = om.add_lin_constraint(sprintf('CHANCE_LINE_LIMITS_t%03d', t), Afull, l, u);
    end

    % ----------------------------
    % (B) Reactive reserve addition
    % ----------------------------
    % Add variable Qres (per generator)
    Qres_min = zeros(ng, 1);
    Qres_max = gen(:, QMAX);
    om.add_var(sprintf('Qres_t%03d', t), ng, Qres_min, Qres_max);

    % Update indices after adding var
    idx2 = om.var.idx;
    i1Qg = idx2.i1.Qg; iNQg = idx2.iN.Qg;
    if (iNQg - i1Qg + 1) ~= ng
        % Some DC models might not include Qg in the var set.
        % In that case, skip Qg-coupled constraints and only enforce a standalone reserve requirement.
        haveQg = false;
    else
        haveQg = true;
    end

    i1Qres = idx2.i1.(sprintf('Qres_t%03d', t));
    iNQres = idx2.iN.(sprintf('Qres_t%03d', t));

    nv2 = om.var.N;

    % Capability constraint: Qg_i + Qres_i <= Qmax_i
    if haveQg
        A_qres = sparse(ng, nv2);
        for i = 1:ng
            A_qres(i, i1Qg + (i-1))   = 1;
            A_qres(i, i1Qres + (i-1)) = 1;
        end
        om.add_lin_constraint(sprintf('qres_cap_t%03d', t), A_qres, [], gen(:, QMAX));
    end

    % System reserve requirement: sum(Qres) >= alpha * total_Pd
    total_load = sum(bus(:, PD));
    Qres_req = qres.alpha * total_load;
    A_req = sparse(1, nv2);
    A_req(1, i1Qres:iNQres) = 1;
    om.add_lin_constraint(sprintf('req_Qres_t%03d', t), A_req, Qres_req, inf);

    % Add linear cost on Qres (via quadratic cost interface with Q=0)
    c = zeros(nv2, 1);
    c(i1Qres:iNQres) = qres.w * ones(ng, 1);
    Q = sparse(nv2, nv2);
    k = 0;
    om.add_quad_cost(sprintf('qreserve_cost_t%03d', t), Q, c, k);

    % Write back
    mdo.flow(t).om = om;
    mdo.flow(t).mpc = mpc_i;
end
end

function z = norminv_approx(p)
% Compute z = Phi^{-1}(p) without requiring Statistics Toolbox.
z = -sqrt(2) * erfcinv(2*p);
end

clear; clc;
define_constants;

%% ========================= Load base case =========================
mpc = loadcase('case118zh');

%% ========================= Solver / options =========================
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'DC');
mpopt = mpoption(mpopt, 'opf.dc.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-8);

%% ========================= Parameter modification =========================
% Generator at bus 8: scale COST_PARAMS_C3 by 1.1
% (Assumes polynomial gencost MODEL=2 with rows aligned to mpc.gen)
idx_g8 = find(mpc.gen(:, GEN_BUS) == 8);
if isempty(idx_g8)
    error('No generator found at bus 8.');
end
if size(mpc.gencost, 1) < max(idx_g8)
    error('gencost rows do not align with gen rows (cannot safely edit).');
end
for kk = 1:numel(idx_g8)
    r = idx_g8(kk);
    if mpc.gencost(r, MODEL) ~= 2
        error('Generator cost at gen row %d is not polynomial (MODEL=2).', r);
    end
    ncost = mpc.gencost(r, NCOST);
    % COST_PARAMS_C3 corresponds to cubic coefficient if present.
    % For polynomial with NCOST=k, coefficients occupy columns 5..(4+k)
    % Highest order coefficient is at column 5.
    % If NCOST>=4 => cubic term exists.
    if ncost >= 4
        c_col = 5; % highest-order coefficient
        mpc.gencost(r, c_col) = 1.1 * mpc.gencost(r, c_col);
    else
        warning('Gen at bus 8 has NCOST=%d < 4; no cubic coefficient to scale.', ncost);
    end
end

%% ========================= Structural modification A: load shedding =========================
% Add one virtual generator per load bus with Pg representing shed load.
load_buses = find(mpc.bus(:, PD) > 0);
nl_load = length(load_buses);
ng0 = size(mpc.gen, 1);

ncol_gen = size(mpc.gen, 2);
new_gen  = zeros(nl_load, ncol_gen);
for k = 1:nl_load
    b = load_buses(k);
    Pd_k = mpc.bus(b, PD);

    g = mpc.gen(1, :); % template
    g(GEN_BUS)    = b;
    g(PG)         = 0;
    g(QG)         = 0;
    g(QMAX)       = 0;
    g(QMIN)       = 0;
    g(VG)         = 1.0;
    g(GEN_STATUS) = 1;
    g(PMAX)       = Pd_k;
    g(PMIN)       = 0;

    new_gen(k, :) = g;
end

mpc.gen = [mpc.gen; new_gen];
ng = size(mpc.gen, 1);
shed_gen_idx = (ng0+1:ng)';

% Append corresponding gencost rows for load shedding units
ncol_gc = size(mpc.gencost, 2);
old_cost = mpc.gencost;

p_cost = 100  * ones(nl_load, 1);
q_cost = 1000 * ones(nl_load, 1);
r_cost = 5000 * ones(nl_load, 1);

new_cost = zeros(nl_load, ncol_gc);
new_cost(:, 1) = 2;  % MODEL = polynomial
new_cost(:, 2) = 0;  % STARTUP
new_cost(:, 3) = 0;  % SHUTDOWN
new_cost(:, 4) = 3;  % NCOST = 3 -> [c2 c1 c0]

% Ensure there is room for polynomial coefficients
if ncol_gc < 7
    error('gencost has only %d columns; expected at least 7 for quadratic costs.', ncol_gc);
end
new_cost(:, 5) = r_cost;
new_cost(:, 6) = q_cost;
new_cost(:, 7) = p_cost;

mpc.gencost = [old_cost; new_cost];

%% ========================= Structural modification B: robust line constraints (box) =========================
% Uncertainty definition (external bus numbers)
unc_buses_ext = [5; 9];
Delta_MW      = [30; 20];

% Prepare branch limits: replace missing RATE_A
rateA = mpc.branch(:, RATE_A);
if all(rateA == 0)
    mpc.branch(:, RATE_A) = 250;
else
    mpc.branch(rateA == 0, RATE_A) = 1e4;
end

% Work in internal indexing for PTDF and OPF model
mpc_i   = ext2int(mpc);
baseMVA = mpc_i.baseMVA;
bus     = mpc_i.bus;
branch  = mpc_i.branch;
gen     = mpc_i.gen;

nb = size(bus, 1);
nbr = size(branch, 1);
ng_i = size(gen, 1);

% PTDF matrix
PTDF = makePTDF(baseMVA, bus, branch); % nbr x nb

% Generator-bus incidence matrix
Cg = sparse(gen(:, GEN_BUS), (1:ng_i)', 1, nb, ng_i);
Pd = bus(:, PD) / baseMVA;

% Map external uncertain buses to internal indices using original case mapping
% (use base case118zh for mapping consistency)
mpc0 = loadcase('case118zh');
mpc0_i = ext2int(mpc0);
unc_buses_int = zeros(size(unc_buses_ext));
for k = 1:numel(unc_buses_ext)
    bi = find(mpc0_i.bus(:, BUS_I) == unc_buses_ext(k), 1);
    if isempty(bi)
        error('Uncertain bus ext #%d not found in case118zh.', unc_buses_ext(k));
    end
    unc_buses_int(k) = bi;
end

Delta_pu = Delta_MW(:) / baseMVA;
PTDF_U = PTDF(:, unc_buses_int);
worst  = abs(PTDF_U) * Delta_pu;     % nbr x 1
Fmax   = branch(:, RATE_A) / baseMVA;

% Build OPF model and add robust linear constraints
om = opf_setup(mpc_i, mpopt);
idx = om.var.idx;
i1 = idx.i1.Pg;
iN = idx.iN.Pg;
nv = om.var.N;

if (iN - i1 + 1) ~= ng_i
    error('Pg dimension mismatch in OM.');
end

Arows = [];
lvec  = [];
uvec  = [];

for ell = 1:nbr
    if branch(ell, BR_STATUS) == 0
        continue;
    end
    if Fmax(ell) <= 0
        continue;
    end

    margin = Fmax(ell) - worst(ell);
    a_pg   = PTDF(ell, :) * Cg;     % 1 x ng
    const  = PTDF(ell, :) * (-Pd);  % scalar

    rhs_pos = margin - const;
    rhs_neg = margin + const;

    % mu_f <= margin
    Arows(end+1, :) =  a_pg; %#ok<SAGROW>
    lvec(end+1, 1)  = -Inf;
    uvec(end+1, 1)  =  rhs_pos;

    % -mu_f <= margin
    Arows(end+1, :) = -a_pg; %#ok<SAGROW>
    lvec(end+1, 1)  = -Inf;
    uvec(end+1, 1)  =  rhs_neg;
end

if ~isempty(Arows)
    A = sparse(Arows);
    Afull = sparse(size(A, 1), nv);
    Afull(:, i1:iN) = A;
    om = om.add_lin_constraint('ROBUST_LINE_LIMITS_BOX', Afull, lvec, uvec);
end

%% ========================= Solve =========================
try
    [res_i, success] = opf_execute(om, mpopt);
catch
    [res_i, success] = opf_execute(om, mpc_i, mpopt);
end

if ~success
    error('Robust DCOPF with load shedding failed (infeasible or did not converge).');
end

results = int2ext(res_i, mpc);

%% ========================= Post-processing / checks =========================
Pg_all = results.gen(:, PG);
Lshd   = Pg_all(shed_gen_idx);
orig_load = mpc.bus(load_buses, PD);
remain_load = orig_load - Lshd;

total_orig   = sum(orig_load);
total_shed   = sum(Lshd);
total_remain = total_orig - total_shed;

% Ex-post robust check in internal space
Pg_pu = res_i.gen(:, PG) / baseMVA;
mu_f  = PTDF * (Cg * Pg_pu - Pd);
lhs   = abs(mu_f) + worst;
viol  = max(lhs - Fmax, 0);

fprintf('\n=== Robust DCOPF with Load Shedding (case118zh) ===\n');
fprintf('Total objective           = %.6f\n', results.f);
fprintf('Total original load (MW)  = %10.3f\n', total_orig);
fprintf('Total shed load (MW)      = %10.3f\n', total_shed);
fprintf('Total remaining load (MW) = %10.3f\n', total_remain);
fprintf('Overall shed ratio (%%)     = %10.3f\n', 100 * total_shed / max(total_orig, 1e-9));
fprintf('Max robust flow violation  = %.6g p.u. (%.6g MW)\n', max(viol), max(viol) * baseMVA);

% Optional: print a brief shedding summary (first 20 loads)
ns = min(nl_load, 20);
fprintf('\nBus  OrigLoad  ShedLoad  RemainLoad  ShedRatio(%%)\n');
for k = 1:ns
    b = load_buses(k);
    fprintf('%3d  %8.3f  %8.3f  %10.3f   %8.2f\n', ...
        b, orig_load(k), Lshd(k), remain_load(k), 100 * Lshd(k) / max(orig_load(k), 1e-9));
end

clear; clc;
define_constants;

%% ==================== Load case & options ====================
mpc0 = loadcase('case5');
if isempty(mpc0)
    error('Failed to load case5');
end

mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'DC');
mpopt = mpoption(mpopt, 'opf.dc.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);

%% ==================== Parameter modifications ====================
% (1) Bus 3, VMAX -> scale to 1.04 (interpreted as set to 1.04)
bus_id = 3;
b3 = find(mpc0.bus(:, BUS_I) == bus_id);
if isempty(b3)
    error('Bus %d not found in case', bus_id);
end
mpc0.bus(b3, VMAX) = 1.04;

% (2) Generator at bus 2, COST_PARAMS_C3 (quadratic coeff for polynomial cost) scale 1.1
% For POLYNOMIAL costs with NCOST=3: cost = c2*Pg^2 + c1*Pg + c0
% In gencost, coefficients are in columns: (end-2:end) => [c2 c1 c0]
gbus = 2;
gidx = find(mpc0.gen(:, GEN_BUS) == gbus);
if isempty(gidx)
    error('No generator found at bus %d', gbus);
end
% choose first generator at bus 2 if multiple
ig = gidx(1);
if mpc0.gencost(ig, MODEL) ~= POLYNOMIAL
    error('Generator cost model for gen at bus %d is not POLYNOMIAL; cannot scale quadratic coefficient.', gbus);
end
ncost = mpc0.gencost(ig, NCOST);
if ncost < 3
    error('Generator cost has NCOST=%d (<3); no quadratic coefficient to scale.', ncost);
end
c2_col = size(mpc0.gencost, 2) - (ncost - 1); % first coefficient column index
% coefficients start at c2_col, ..., end
% for NCOST=3, c2 is at c2_col
mpc0.gencost(ig, c2_col) = 1.1 * mpc0.gencost(ig, c2_col);

% (3) Branch (3->4), BR_X scale 1.1
fbus = 3; tbus = 4;
br = find(mpc0.branch(:, F_BUS) == fbus & mpc0.branch(:, T_BUS) == tbus);
if isempty(br)
    error('Branch %d->%d not found in case', fbus, tbus);
end
% if multiple parallel lines, scale all that match
mpc0.branch(br, BR_X) = 1.1 * mpc0.branch(br, BR_X);

%% ==================== Build DC-SCOPF model (N-1 constraints) ====================
% Use internal indexing for PTDF/LODF consistency
mpc = ext2int(mpc0);
baseMVA = mpc.baseMVA;
bus    = mpc.bus;
branch = mpc.branch;

nb = size(bus, 1);
nl = size(branch, 1);

% DC matrices & sensitivities
[~, Bf, ~, Pfinj] = makeBdc(baseMVA, bus, branch);
PTDF = makePTDF(baseMVA, bus, branch);
LODF = makeLODF(branch, PTDF);

in_service = (branch(:, BR_STATUS) == 1);
has_limit  = (branch(:, RATE_A) > 0);

% Contingency set: in-service branches with limits
cont_set = find(in_service & has_limit);
nc = length(cont_set);
if nc == 0
    error('Contingency set is empty (no in-service branches with RATE_A>0).');
end

% Lines to constrain in post-contingency limits
constrain_lines = find(in_service & has_limit);
nL = length(constrain_lines);

% Build OPF model
om = opf_setup(mpc, mpopt);
nv = om.var.N;

iVa1 = om.var.idx.i1.Va;
iVaN = om.var.idx.iN.Va;

rateA = branch(:, RATE_A);

% Build linear constraints: for each contingency k and each constrained line ell,
% enforce: -RATE_A <= f_ell^(k) <= RATE_A, where f_ell^(k) = Bf_k(ell,:)*Va + Pf_k(ell)

nRows = 2 * nL * nc;
A = spalloc(nRows, nv, 2 * nL * nc * nb);
l = -inf(nRows, 1);
u =  inf(nRows, 1);

row = 0;
for kk = 1:nc
    k = cont_set(kk);

    lodf_col = LODF(:, k);   % nl x 1
    Bf_row_k = Bf(k, :);     % 1 x nb
    Pk       = Pfinj(k);     % scalar

    % Post-contingency flow mapping
    Bf_k = Bf + lodf_col * Bf_row_k;  % nl x nb
    Pf_k = Pfinj + lodf_col * Pk;     % nl x 1

    for ii = 1:nL
        ell = constrain_lines(ii);
        limit = rateA(ell);

        aVa = Bf_k(ell, :);
        cst = Pf_k(ell);

        % f <= limit  => aVa*Va <= limit - cst
        row = row + 1;
        A(row, iVa1:iVaN) = aVa;
        u(row) = limit - cst;

        % -f <= limit => -aVa*Va <= limit + cst
        row = row + 1;
        A(row, iVa1:iVaN) = -aVa;
        u(row) = limit + cst;
    end
end

if row ~= nRows
    error('Row count mismatch in contingency constraint build: row=%d, expected=%d', row, nRows);
end

om.add_lin_constraint('N1_branch_limits', A, l, u);

%% ==================== Objective modification: add Qg quadratic cost ====================
% Add sum(c_Q .* Qg.^2) even though physics are DC; Qg variables still exist
% in the OPF model and this term regularizes/penalizes reactive dispatch.
idx_i1 = om.var.idx.i1;
idx_iN = om.var.idx.iN;
ng = idx_iN.Pg - idx_i1.Pg + 1;

% Define per-generator reactive cost weights (edit as desired)
% Use a simple default for case5: moderate penalties
c_Q = 10 * ones(ng, 1);

Q_mat = sparse(1:ng, 1:ng, 2*c_Q, ng, ng);
om = om.add_quad_cost('reactive_support_cost', Q_mat, [], 0, {'Qg'});

%% ==================== Solve ====================
[x, f, eflag, output, lambda] = om.solve();

results = mpc;
results.success = (eflag > 0);
results.f = f;
results.eflag = eflag;
results.output = output;
results.lambda = lambda;

if results.success
    Va_solution = x(idx_i1.Va:idx_iN.Va);
    Pg_solution = x(idx_i1.Pg:idx_iN.Pg);

    % Qg may or may not exist depending on formulation, but in MATPOWER OPF it does.
    if isfield(idx_i1, 'Qg') && isfield(idx_iN, 'Qg')
        Qg_solution = x(idx_i1.Qg:idx_iN.Qg);
        results.gen(:, QG) = Qg_solution;
    end

    results.bus(:, VA) = Va_solution * 180/pi;
    results.gen(:, PG) = Pg_solution;
else
    warning('OPF failed, eflag = %d', eflag);
end

% convert back to external indexing for reporting
results = int2ext(results);

fprintf('\n=== DC-SCOPF (case5) solved ===\n');
fprintf('Success: %d\n', results.success);
fprintf('Objective value: %.6f\n', results.f);
if isfield(results, 'output') && isfield(results.output, 'iterations')
    fprintf('Iterations: %d\n', results.output.iterations);
end

fprintf('\nGenerator PG (MW):\n');
disp(results.gen(:, PG));

fprintf('Bus VA (deg):\n');
disp(results.bus(:, VA));

define_constants;
clear; clc;

%% Load base case
mpc = loadcase('case94pi');

%% -------------------------
%% Parameter modifications
%% -------------------------
% 1) Bus 47, VMIN: set to 0.99
b47 = find(mpc.bus(:, BUS_I) == 47);
if isempty(b47)
    error('Bus 47 not found in case94pi');
end
mpc.bus(b47, VMIN) = 0.99;

% 2) Bus 6, VMAX: scale to 1.02 * original
b6 = find(mpc.bus(:, BUS_I) == 6);
if isempty(b6)
    error('Bus 6 not found in case94pi');
end
mpc.bus(b6, VMAX) = 1.02 * mpc.bus(b6, VMAX);

% 3) Bus 38, QD: scale to 0 (set to zero)
b38 = find(mpc.bus(:, BUS_I) == 38);
if isempty(b38)
    error('Bus 38 not found in case94pi');
end
mpc.bus(b38, QD) = 0 * mpc.bus(b38, QD);

%% -------------------------
%% Solver / model settings
%% -------------------------
mpopt = mpoption(...
    'model', 'DC', ...
    'opf.dc.solver', 'MIPS', ...
    'opf.violation', 1e-7, ...
    'verbose', 2);

%% Run DCOPF
result = rundcopf(mpc, mpopt);

%% Report
fprintf('Total cost: %.6f\n', result.f);

clear; clc;

%% Level 3 ACOPF (case6ww) + ED objective + frequency-inspired constraints
%% - Base modifications:
%%   (1) Gen @ bus 3: PMIN = 0
%%   (2) Branch 6->4: BR_B scaled by 1.1
%% - Structural mods:
%%   AC OPF (MIPS) + auxiliary variables (Pmax_var, R) and linear constraints

define_constants;
mpc = loadcase('case6ww');

%% ======================== Base parameter modifications ========================
% (1) Generator at bus 3: PMIN = 0
idx_g3 = find(mpc.gen(:, GEN_BUS) == 3);
if isempty(idx_g3)
    error('No generator found at bus 3 in case6ww.');
end
mpc.gen(idx_g3, PMIN) = 0;

% (2) Branch (6 -> 4): BR_B scaled by 1.1
idx_br_64 = find(mpc.branch(:, F_BUS) == 6 & mpc.branch(:, T_BUS) == 4);
if isempty(idx_br_64)
    error('No branch found with F_BUS=6, T_BUS=4 in case6ww.');
end
mpc.branch(idx_br_64, BR_B) = 1.1 * mpc.branch(idx_br_64, BR_B);

%% ======================== OPF options / solve requirements ========================
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'AC');
mpopt = mpoption(mpopt, 'opf.ac.solver', 'MIPS');

% Tight feasibility tolerance ("opf_violation")
% Note: MATPOWER uses 'opf.violation' in mpoption.
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);

%% ======================== Frequency constraint parameters ========================
% User-provided / template defaults
f0 = 60;                  % Hz
RoCoF_max = 0.5;          % Hz/s
df_req = 0.5;             % Hz
D_MW_per_Hz = 0;          % MW/Hz (set 0 for conservative if unknown)

%% ======================== Build OPF model with extra vars/constraints ========================
mpc_i = ext2int(mpc);
om = opf_setup(mpc_i, mpopt);

ng = size(mpc_i.gen, 1);

% Inertia constants H_i (seconds). Case data typically does not include these.
H = 5 * ones(ng, 1);

% Unit sizes S_i (MVA). Prefer GEN_MBASE; if <= 0 fallback to PMAX.
S_i = mpc_i.gen(:, MBASE);
bad = S_i <= 0;
S_i(bad) = mpc_i.gen(bad, PMAX);

S_base = mpc_i.baseMVA;
H_sys = (H(:)' * S_i(:)) / S_base;
Ptrip_max_rocof = 2 * H_sys * S_base * RoCoF_max / f0;

% Reserve upper bounds (optional). Keep +Inf unless you want explicit caps.
Rmax = +Inf * ones(ng, 1);

% Indices for existing Pg vars
idx = om.var.idx;
iPg1 = idx.i1.Pg;
iPgN = idx.iN.Pg;

% Add new variables
om = om.add_var('Pmax_var', 1, 0, Inf, 0);
om = om.add_var('R', ng, zeros(ng,1), Rmax, 0);

% Refresh indexing after adding vars
nv = om.var.N;
iPmax = om.var.idx.i1.Pmax_var;
iR1   = om.var.idx.i1.R;
iRN   = om.var.idx.iN.R;

PMAX = mpc_i.gen(:, PMAX);

% (i) Pg_i <= Pmax_var
A = sparse(ng, nv);
A(:, iPg1:iPgN) = speye(ng);
A(:, iPmax)     = -ones(ng, 1);
om = om.add_lin_constraint('MAX_TRIP_DEF', A, -Inf(ng,1), zeros(ng,1));

% (ii) Pg_i + R_i <= PMAX_i
A = sparse(ng, nv);
A(:, iPg1:iPgN) = speye(ng);
A(:, iR1:iRN)   = speye(ng);
om = om.add_lin_constraint('RESERVE_HEADROOM', A, -Inf(ng,1), PMAX);

% (iii) RoCoF: Pmax_var <= Ptrip_max_rocof
A = sparse(1, nv);
A(1, iPmax) = 1;
om = om.add_lin_constraint('ROCOF_LIMIT', A, -Inf, Ptrip_max_rocof);

% (iv) Frequency nadir proxy: Pmax_var - sum(R) <= D * df_req
A = sparse(1, nv);
A(1, iPmax)   = 1;
A(1, iR1:iRN) = -ones(1, ng);
om = om.add_lin_constraint('DF_LIMIT_RESERVE', A, -Inf, D_MW_per_Hz * df_req);

%% ======================== Solve ========================
[res_i, success] = opf_execute(om, mpopt);
if ~success
    error('ACOPF + frequency constraints failed (likely infeasible).');
end
results = int2ext(res_i, mpc);

%% ======================== Extract & print ========================
Pmax_val = res_i.var.val(iPmax);
R = res_i.var.val(iR1:iRN);

fprintf('\n=== ACOPF + Frequency Constraints Summary ===\n');
fprintf('case=case6ww, opf.violation=1e-6\n');
fprintf('f0=%.1f Hz, RoCoF_max=%.3f Hz/s, df_req=%.3f Hz, D=%.3f MW/Hz\n', ...
    f0, RoCoF_max, df_req, D_MW_per_Hz);
fprintf('H_sys=%.6f s, Ptrip_max_rocof=%.6f MW\n', H_sys, Ptrip_max_rocof);
fprintf('Pmax_var=%.6f MW\n', Pmax_val);
fprintf('Sum reserve=%.6f MW\n', sum(R));
fprintf('Objective=%.6f\n', results.f);

fprintf('\nGenerator dispatch (Pg, MW):\n');
disp(results.gen(:, [GEN_BUS PG PMIN PMAX]));

fprintf('Reserve variables R (MW) in internal generator order:\n');
disp(R);

clear; clc;
define_constants;

%% ===================== 1) Load case & options =====================
casefile = 'case89pegase';
mpc0 = loadcase(casefile);

verbose = 1;
mpopt = mpoption('verbose', verbose);
mpopt = mpoption(mpopt, 'out.gen', 1);
mpopt = mpoption(mpopt, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'DC');
mpopt = mpoption(mpopt, 'most.solver', 'OT');
mpopt = mpoption(mpopt, 'most.price_stage_warn_tol', 1e-5);
mpopt = mpoption(mpopt, 'most.dc_model', 1);

% required tolerance
mpopt = mpoption(mpopt, 'opf.violation', 1e-7);

% tighten MILP tolerances if available
if have_feature('intlinprog')
    mpopt = mpoption(mpopt, 'linprog.Algorithm', 'dual-simplex');
    mpopt = mpoption(mpopt, 'intlinprog.RootLPAlgorithm', 'dual-simplex');
    mpopt = mpoption(mpopt, 'intlinprog.TolCon', 1e-9);
    mpopt = mpoption(mpopt, 'intlinprog.TolGapAbs', 0);
    mpopt = mpoption(mpopt, 'intlinprog.TolGapRel', 0);
    mpopt = mpoption(mpopt, 'intlinprog.TolInteger', 1e-6);
end

%% ===================== 2) Base parameter modifications =====================
mpc = mpc0;

% (a) Bus 9, BS = 0.2
b9 = find(mpc.bus(:, BUS_I) == 9, 1);
if isempty(b9), error('Bus 9 not found in %s.', casefile); end
mpc.bus(b9, BS) = 0.2;

% (b) Bus 20, QD scaled by 1.2
b20 = find(mpc.bus(:, BUS_I) == 20, 1);
if isempty(b20), error('Bus 20 not found in %s.', casefile); end
mpc.bus(b20, QD) = 1.2 * mpc.bus(b20, QD);

% (c) Generator at bus 3, quadratic cost coefficient (C2) scaled by 0.9
% MATPOWER gencost for polynomial: [MODEL STARTUP SHUTDOWN NCOST c(n-1) ... c0]
% For NCOST=3, columns are: c2 c1 c0.
g3 = find(mpc.gen(:, GEN_BUS) == 3, 1);
if isempty(g3)
    error('No generator found at bus 3 in %s.', casefile);
end
if size(mpc.gencost, 2) < COST
    error('gencost appears malformed.');
end
if mpc.gencost(g3, MODEL) ~= POLYNOMIAL
    error('Generator cost at bus 3 is not polynomial; cannot scale C2 reliably.');
end
ncost = mpc.gencost(g3, NCOST);
if ncost < 3
    error('Generator at bus 3 does not have a quadratic term (NCOST < 3).');
end
c2_col = COST; % first cost coefficient column (c_{ncost-1})
mpc.gencost(g3, c2_col) = 0.9 * mpc.gencost(g3, c2_col);

%% ===================== 3) Multi-period UC data, profiles, wind, storage =====================
% These auxiliary data files are expected to exist on the MATLAB path.
% They can be replaced with appropriate datasets for case89pegase.

xgd = loadxgendata('ex_xgd_uc', mpc);

% Wind and load profiles (MOST profiles)
[iwind, mpc, xgd] = addwind('ex_wind_uc', mpc, xgd);

windprofile = struct( ...
    'type', 'mpcData', ...
    'table', CT_TGEN, ...
    'rows', 1, ...
    'col', PMAX, ...
    'chgtype', CT_REL, ...
    'values', [] );

wp = ex_wind_profile;
windprofile.values(:, :, 1) = mean(wp.values, 2);
profiles = getprofiles(windprofile, iwind);
profiles = getprofiles('ex_load_profile', profiles);
nt = size(profiles(1).values, 1);

% Example edits of startup/shutdown costs (only if indices exist)
if size(mpc.gencost, 1) >= 3
    mpc.gencost(2, [STARTUP SHUTDOWN]) = [300 300];
    mpc.gencost(3, [STARTUP SHUTDOWN]) = [2000 500];
end

% Example min up/down edits if xgd has enough units
if isfield(xgd, 'MinUp') && numel(xgd.MinUp) >= 2
    xgd.MinUp(2) = 2;
end
if isfield(xgd, 'MinDown') && numel(xgd.MinDown) >= 3
    xgd.MinDown(3) = 2;
end

% Example ramp reserve quantities/prices if present
if isfield(xgd, 'PositiveLoadFollowReserveQuantity') && numel(xgd.PositiveLoadFollowReserveQuantity) >= 3
    xgd.PositiveLoadFollowReserveQuantity(3) = 120;
end
if isfield(xgd, 'PositiveLoadFollowReservePrice') && numel(xgd.PositiveLoadFollowReservePrice) >= 3
    xgd.PositiveLoadFollowReservePrice(3) = 10;
end
if isfield(xgd, 'NegativeLoadFollowReservePrice') && numel(xgd.NegativeLoadFollowReservePrice) >= 3
    xgd.NegativeLoadFollowReservePrice(3) = 10;
end

% Storage
mpopt = mpoption(mpopt, 'most.storage.cyclic', 1);
[iess, mpc, xgd, sd] = addstorage('ex_storage', mpc, xgd); %#ok<ASGLU>

%% ===================== 4) Chance-constraint parameters =====================
% Stochastic injection bus (external numbering)
w_bus_ext = 9;
mu_w_MW    = 60;
sigma_w_MW = 20;

eps_cc = 0.05;
z_cc = norminv_approx(1 - eps_cc/2);

% Ensure RATE_A exists / nonzero to avoid degenerate thermal limits
rateA = mpc.branch(:, RATE_A);
if all(rateA == 0)
    mpc.branch(:, RATE_A) = 250;
else
    mpc.branch(rateA == 0, RATE_A) = 1e4;
end

% Embed mean stochastic injection as negative load at wind bus (mean model)
bw = find(mpc.bus(:, BUS_I) == w_bus_ext, 1);
if isempty(bw), error('Chance constraint wind bus %d not found.', w_bus_ext); end
mpc.bus(bw, PD) = mpc.bus(bw, PD) - mu_w_MW;

%% ===================== 5) Build MOST model =====================
mdi = loadmd(mpc, nt, xgd, sd, [], profiles);

% First run MOST to build/solve baseline SCUC
mdo0 = most(mdi, mpopt);
if verbose
    most_summary(mdo0);
end

%% ===================== 6) Augment MOST problem with L-index objective + chance constraints =====================
% NOTE: This section assumes MOST returns an optimization model handle in mdo.
% In some MOST/MATPOWER versions, the model is accessible via mdo.om (or mdo.QP/miqps struct).
% If your version differs, adapt the accessors accordingly.

if ~isfield(mdo0, 'om')
    error(['This script expects MOST output to include an Optimization Model (mdo.om). ' ...
           'Your MOST/MATPOWER version may use a different field name; adapt accordingly.']);
end

om = mdo0.om;

% Weight for L-index cost
lambda_L = 1.0;

% Build Ybus/F-matrix once from the (modified) base network data
% (Used as a proxy for a stability metric; applied using per-period voltages if available.)
% Since SCUC is DC, Vm is typically fixed and Va is the relevant state.
% We still compute the L-index from Ybus partitioning using complex V built from Va and Vm=1.
[Ybus, ~, ~] = makeYbus(mpc.baseMVA, mpc.bus, mpc.branch);

bus_type = mpc.bus(:, BUS_TYPE);
idxG = find(bus_type == REF | bus_type == PV);
idxL = find(bus_type == PQ);
if isempty(idxL)
    warning('No PQ buses found; L-index term will be zero.');
end
Y_LL = Ybus(idxL, idxL);
Y_LG = Ybus(idxL, idxG);
Fmat = -(Y_LL \ Y_LG);

% Add an nln cost that sums Lmax over time, using Va variables if available.
% We attempt to locate Va in OM. If Va is not present in the MOST SCUC model,
% we fall back to a zero cost (objective unaffected).
try
    idx = om.var.idx;
    haveVa = isfield(idx.i1, 'Va') && isfield(idx.iN, 'Va');
catch
    haveVa = false;
end

if haveVa && ~isempty(idxL)
    fcn = @(x) l_index_cost_most_fcn(x, lambda_L, om, Fmat, idxG, idxL, nt);
    om.add_nln_cost('L_index_cost', 1, fcn);
else
    warning('Va block not found in OM (or no PQ buses). Skipping L-index objective term.');
end

% Add chance constraints on line limits for each time period using PTDF.
% We approximate per-period Pd using the base-case Pd scaled by profiles, but enforce
% conservative constraints using the maximum Pd multiplier across periods if profiles exist.

mpc_i = ext2int(mpc);
baseMVA = mpc_i.baseMVA;
bus_i = mpc_i.bus;
branch_i = mpc_i.branch;
gen_i = mpc_i.gen;

nb = size(bus_i, 1);
nl = size(branch_i, 1);
ng = size(gen_i, 1);

PTDF = makePTDF(baseMVA, bus_i, branch_i); % nl x nb
Cg = sparse(gen_i(:, GEN_BUS), (1:ng)', 1, nb, ng);

% internal index of wind bus
tmp = ext2int(mpc0); % mapping from original case (before mean-load embedding)
w_bus_int = find(tmp.bus(:, BUS_I) == w_bus_ext, 1);
if isempty(w_bus_int), error('Wind bus internal mapping failed.'); end

sigma_w_pu = sigma_w_MW / baseMVA;
ptdf_w = PTDF(:, w_bus_int);
sigma_f = abs(ptdf_w) * sigma_w_pu;
Fmax = branch_i(:, RATE_A) / baseMVA;

% Demand vector Pd (use current mean-embedded mpc_i)
Pd0 = bus_i(:, PD) / baseMVA;

% Conservative scaling for Pd over time (if load profile exists)
load_mult = 1;
try
    % ex_load_profile typically scales PD/QD via CT_TBUS modifications.
    % Here we conservatively take the max multiplier appearing in profiles.
    for k = 1:numel(profiles)
        if isfield(profiles(k), 'table') && profiles(k).table == CT_TBUS && profiles(k).col == PD
            vals = profiles(k).values;
            load_mult = max(load_mult, max(vals(:)));
        end
    end
catch
end
Pd_cons = load_mult * Pd0;

% Identify Pg block(s) in OM.
% MOST is multi-period, so Pg can appear as a stacked variable or per-period blocks.
% We handle the common case where Pg is stacked as a single block of length ng*nt.
idx = om.var.idx;
if ~isfield(idx.i1, 'Pg')
    warning('Pg block not found in OM. Skipping chance constraints.');
else
    i1Pg = idx.i1.Pg;
    iNPg = idx.iN.Pg;
    nPg = iNPg - i1Pg + 1;

    if mod(nPg, ng) ~= 0
        warning('Unexpected Pg dimension in MOST OM; skipping chance constraints.');
    else
        nt_om = nPg / ng;
        if nt_om ~= nt
            warning('OM time periods (%d) differ from profiles nt (%d). Using OM value.', nt_om, nt);
            nt = nt_om;
        end

        nv = om.var.N;
        Arows = [];
        lcon = [];
        ucon = [];
        row_count = 0;

        for t = 1:nt
            % columns for Pg at time t in the stacked block
            col_t = i1Pg + (t-1)*ng : i1Pg + t*ng - 1;

            for ell = 1:nl
                if branch_i(ell, BR_STATUS) == 0
                    continue;
                end

                a_pg = PTDF(ell,:) * Cg;          % 1 x ng
                const = PTDF(ell,:) * (-Pd_cons); % scalar

                margin = Fmax(ell) - z_cc * sigma_f(ell);
                rhs_pos = margin - const;
                rhs_neg = margin + const;

                % mu_f <= margin
                row_count = row_count + 1;
                Arows(row_count, 1:ng) = a_pg; %#ok<AGROW>
                lcon(row_count, 1) = -Inf; %#ok<AGROW>
                ucon(row_count, 1) = rhs_pos; %#ok<AGROW>

                % -mu_f <= margin
                row_count = row_count + 1;
                Arows(row_count, 1:ng) = -a_pg; %#ok<AGROW>
                lcon(row_count, 1) = -Inf; %#ok<AGROW>
                ucon(row_count, 1) = rhs_neg; %#ok<AGROW>
            end

            if row_count > 0
                % add constraints for this time period as a block on Pg(t)
                A = sparse(Arows);
                Afull = sparse(size(A,1), nv);
                Afull(:, col_t) = A;
                cname = sprintf('CHANCE_LINE_LIMITS_T%03d', t);
                om = om.add_lin_constraint(cname, Afull, lcon, ucon);
            end

            % reset per-period accumulators
            Arows = [];
            lcon = [];
            ucon = [];
            row_count = 0;
        end
    end
end

%% ===================== 7) Re-solve augmented model =====================
% Solve the augmented OM.
% Depending on MATPOWER/MOST versions, use om.solve() or opf_execute().

try
    [x, f, eflag, output, lambda] = om.solve(); %#ok<ASGLU>
    success = (eflag > 0);
catch
    try
        [res_i, success, raw] = opf_execute(om, mpopt); %#ok<NASGU>
    catch
        [res_i, success, raw] = opf_execute(om, mpc_i, mpopt); %#ok<NASGU>
    end
end

if ~success
    error('Augmented multi-period SCUC failed. Consider relaxing eps/sigma, or increasing RATE_A.');
end

fprintf('\n=== Level-3 Multi-period SCUC summary (augmented) ===\n');
fprintf('case: %s, nt=%d\n', casefile, nt);
fprintf('opf.violation = %.1e\n', 1e-7);
fprintf('Chance constraints: eps=%.3g, z=%.4f, mu_w=%.2f MW, sigma_w=%.2f MW at bus %d\n', ...
    eps_cc, z_cc, mu_w_MW, sigma_w_MW, w_bus_ext);
if haveVa
    fprintf('L-index objective weight lambda_L = %.4g\n', lambda_L);
end

%% ===================== helper functions =====================
function z = norminv_approx(p)
% Phi^{-1}(p) = -sqrt(2) * erfcinv(2p)
z = -sqrt(2) * erfcinv(2*p);
end

function [f, df, d2f] = l_index_cost_most_fcn(x, lambda_L, om, Fmat, idxG, idxL, nt)
% Sum of per-period Lmax, approximating Vm=1 and using Va from the model.
% Uses finite differences for gradients; Hessian set to 0.

idx = om.var.idx;
nv = om.var.N;

% Va is assumed stacked by time with length nb*nt
i1Va = idx.i1.Va;
iNVa = idx.iN.Va;
nVa = iNVa - i1Va + 1;
nb = nVa / nt;

if abs(nb - round(nb)) > 1e-9
    error('Va dimension is not consistent with nt in l_index_cost.');
end
nb = round(nb);

f = 0;
for t = 1:nt
    Va_t = x(i1Va + (t-1)*nb : i1Va + t*nb - 1);
    Vm_t = ones(nb, 1);
    V = Vm_t .* exp(1j * Va_t);

    V_G = V(idxG);
    V_L = V(idxL);

    T = Fmat * V_G;
    U = T ./ V_L;
    Lvec = abs(1 - U);
    Lmax = max(Lvec);

    f = f + lambda_L * Lmax;
end

if nargout > 1
    eps_fd = 1e-7;
    df = zeros(nv, 1);
    for k = 1:nv
        x_plus = x;
        x_plus(k) = x_plus(k) + eps_fd;
        f_plus = l_index_cost_most_fcn(x_plus, lambda_L, om, Fmat, idxG, idxL, nt);
        df(k) = (f_plus - f) / eps_fd;
    end
end

if nargout > 2
    d2f = sparse(nv, nv);
end
end

define_constants;

%% ======================= Load case =======================
mpc = loadcase('case33mg');

%% ================== Parameter modifications ==============
% 1) Bus 20, BS = 0.2
mpc.bus(20, BS) = 0.2;

% 2) Bus 17, VMIN = 1
mpc.bus(17, VMIN) = 1.0;

% 3) Branch (1->14), BR_X scaled by 1.2
f = mpc.branch(:, F_BUS);
t = mpc.branch(:, T_BUS);
i_1_14 = find(f == 1 & t == 14, 1);
if isempty(i_1_14)
    error('Branch (1->14) not found in case33mg.');
end
mpc.branch(i_1_14, BR_X) = 1.2 * mpc.branch(i_1_14, BR_X);

% 4) Branch (2->18), BR_R scaled by 1.1
i_2_18 = find(f == 2 & t == 18, 1);
if isempty(i_2_18)
    error('Branch (2->18) not found in case33mg.');
end
mpc.branch(i_2_18, BR_R) = 1.1 * mpc.branch(i_2_18, BR_R);

%% ======================= Solver options ===================
mpopt = mpoption('model', 'DC', ...
                 'opf.dc.solver', 'MIPS', ...
                 'opf.violation', 1e-8, ...
                 'verbose', 2, ...
                 'out.all', 0);

%% =========== Build OPF model (for structural mods) ========
% Use internal indexing for consistency with OPF model
mpc_i = ext2int(mpc);
om = opf_setup(mpc_i, mpopt);

nb = size(mpc_i.bus, 1);
ng = size(mpc_i.gen, 1);

%% =================== Add reserve variables =================
% Reserve bounds
Ru_min = zeros(ng, 1);
Rd_min = zeros(ng, 1);
Rs_min = zeros(ng, 1);
Rn_min = zeros(ng, 1);

Ru_max = mpc_i.gen(:, PMAX);
Rd_max = mpc_i.gen(:, PMAX);
Rs_max = mpc_i.gen(:, PMAX);
Rn_max = mpc_i.gen(:, PMAX);

om.add_var('Ru', ng, Ru_min, Ru_max);
om.add_var('Rd', ng, Rd_min, Rd_max);
om.add_var('Rs', ng, Rs_min, Rs_max);
om.add_var('Rn', ng, Rn_min, Rn_max);

% Indices
nv  = om.var.N;
idx = om.var.idx;
i1  = idx.i1;
iN  = idx.iN;

pg_idx = i1.Pg:iN.Pg;
ru_idx = i1.Ru:iN.Ru;
rd_idx = i1.Rd:iN.Rd;
rs_idx = i1.Rs:iN.Rs;
rn_idx = i1.Rn:iN.Rn;

%% ============== Reserve capacity constraints ==============
% (1) Upward capacity: Pg + Ru + Rs + Rn <= PMAX
A_upcap = sparse(ng, nv);
for i = 1:ng
    A_upcap(i, pg_idx(i)) = 1;
    A_upcap(i, ru_idx(i)) = 1;
    A_upcap(i, rs_idx(i)) = 1;
    A_upcap(i, rn_idx(i)) = 1;
end
u_upcap = mpc_i.gen(:, PMAX);
om.add_lin_constraint('cap_up', A_upcap, [], u_upcap);

% (2) Downward capacity: Pg - Rd >= PMIN
A_downcap = sparse(ng, nv);
for i = 1:ng
    A_downcap(i, pg_idx(i)) = 1;
    A_downcap(i, rd_idx(i)) = -1;
end
l_downcap = mpc_i.gen(:, PMIN);
u_downcap = inf(ng, 1);
om.add_lin_constraint('cap_down', A_downcap, l_downcap, u_downcap);

%% ============== System reserve requirements ===============
total_load = sum(mpc_i.bus(:, PD));
R_up_req   = 0.01 * total_load;
R_down_req = 0.01 * total_load;
R_spin_req = 0.01 * total_load;
R_non_req  = 0.01 * total_load;

A_Ru = sparse(1, nv); A_Ru(ru_idx) = 1;
om.add_lin_constraint('req_Ru', A_Ru, R_up_req, inf);

A_Rd = sparse(1, nv); A_Rd(rd_idx) = 1;
om.add_lin_constraint('req_Rd', A_Rd, R_down_req, inf);

A_Rs = sparse(1, nv); A_Rs(rs_idx) = 1;
om.add_lin_constraint('req_Rs', A_Rs, R_spin_req, inf);

A_Rn = sparse(1, nv); A_Rn(rn_idx) = 1;
om.add_lin_constraint('req_Rn', A_Rn, R_non_req, inf);

%% ================== Add reserve linear cost ===============
% Linear cost coefficients
c_u = 3;
c_d = 2;
c_s = 5;
c_n = 1;

% Update nv after var additions (should be unchanged here, but safe)
nv = om.var.N;

c = zeros(nv, 1);
c(ru_idx) = c_u;
