new_cost(:, 5) = r_cost; % c2
new_cost(:, 6) = q_cost; % c1
new_cost(:, 7) = p_cost; % c0

mpc.gencost = [old_cost; new_cost];

%% ========================= Objective modification: network-loss quadratic cost =========================
% Implemented via OPF model (OM) quadratic cost on Pg.
alpha_loss = 10;

% Build a loss model compatible with ng.
% If you have calibrated B-coefficients, replace this block with your data.
B_loss  = 1e-4 * speye(ng);        % diagonal placeholder (ng x ng)
B0_loss = 1e-2 * ones(ng, 1);      % linear placeholder (ng x 1)
B00_loss = 1.0;

%% ========================= Constraint modification: frequency constraints =========================
% Frequency parameters
f0 = 60;              % Hz
RoCoF_max = 0.5;      % Hz/s
df_req = 0.5;         % Hz
D_MW_per_Hz = 0;      % MW/Hz

% Build OM and add constraints/costs
mpc_i = ext2int(mpc);
om = opf_setup(mpc_i, mpopt);

idx = om.var.idx;
iPg1 = idx.i1.Pg; iPgN = idx.iN.Pg;

% Inertia placeholders (must be provided/validated for real studies)
H = 5 * ones(ng, 1);

% Machine base S_i (MVA)
S_i = mpc_i.gen(:, MBASE);
mask = (S_i <= 0);
S_i(mask) = mpc_i.gen(mask, PMAX);

S_base = mpc_i.baseMVA;
H_sys = (H(:)' * S_i(:)) / S_base;
Ptrip_max_rocof = 2 * H_sys * S_base * RoCoF_max / f0;

Rmax = Inf * ones(ng, 1);

% Add variables
om = om.add_var('Pmax_var', 1, 0, Inf, 0);
om = om.add_var('R', ng, zeros(ng, 1), Rmax, 0);

nv = om.var.N;
iPmax = om.var.idx.i1.Pmax_var;
iR1   = om.var.idx.i1.R;
iRN   = om.var.idx.iN.R;

PMAX_i = mpc_i.gen(:, PMAX);

% (i) Pg_i <= Pmax_var
A = sparse(ng, nv);
A(:, iPg1:iPgN) = speye(ng);
A(:, iPmax) = -ones(ng, 1);
om = om.add_lin_constraint('MAX_TRIP_DEF', A, -Inf(ng, 1), zeros(ng, 1));

% (ii) Pg_i + R_i <= PMAX_i
A = sparse(ng, nv);
A(:, iPg1:iPgN) = speye(ng);
A(:, iR1:iRN)   = speye(ng);
om = om.add_lin_constraint('RESERVE_HEADROOM', A, -Inf(ng, 1), PMAX_i);

