A = sparse(1, nv);
A(1, iPmax) = 1;
om = om.add_lin_constraint('ROCOF_LIMIT', A, -Inf, Ptrip_max_rocof);

% (v) df: Pmax_var - sum(R) <= D * df_req
A = sparse(1, nv);
A(1, iPmax) = 1;
A(1, iR1:iRN) = -ones(1, ng);
om = om.add_lin_constraint('DF_LIMIT_RESERVE', A, -Inf, D_MW_per_Hz * df_req);

% Add quadratic network-loss cost: alpha * (Pg' B Pg + B0' Pg + B00)
Q = sparse(nv, nv);
Q(iPg1:iPgN, iPg1:iPgN) = 2 * alpha_loss * B_loss;   % MATPOWER uses (1/2) x'Qx
