end
mpc.bus(bus17, VMIN) = 1.0;

% 3) Branch (1 -> 14), BR_X scaled by 1.2
br_1_14 = find(mpc.branch(:, F_BUS) == 1 & mpc.branch(:, T_BUS) == 14);
if isempty(br_1_14)
