end
mpc.branch(br_1_14, BR_X) = 1.2 * mpc.branch(br_1_14, BR_X);

% 4) Branch (2 -> 18), BR_R scaled by 1.1
br_2_18 = find(mpc.branch(:, F_BUS) == 2 & mpc.branch(:, T_BUS) == 18);
if isempty(br_2_18)
    error('Branch (2->18) not found in case33mg.');
end
mpc.branch(br_2_18, BR_R) = 1.1 * mpc.branch(br_2_18, BR_R);

%% ===================== Solver/options =====================
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'AC');
mpopt = mpoption(mpopt, 'opf.ac.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-8);

%% ===================== Build OPF model =====================
om = opf_setup(mpc, mpopt);

baseMVA = mpc.baseMVA;
nb = size(mpc.bus, 1);
ng = size(mpc.gen, 1);

% Indices for existing variables
idx = om.get_idx();
i1  = idx.i1;
iN  = idx.iN;
nv  = om.var.N;

iPg = i1.Pg:iN.Pg;   % Pg in p.u.
iQg = i1.Qg:iN.Qg;   % Qg in p.u.

%% ===================== Add reactive reserve variables =====================
