Qres_max_pu = Qres_max / baseMVA;

om.add_var('Qres', ng, Qres_min, Qres_max_pu);

% Refresh indices after adding variable
idx = om.get_idx();
i1  = idx.i1;
iN  = idx.iN;
nv  = om.var.N;

iPg = i1.Pg:iN.Pg;
iQg = i1.Qg:iN.Qg;
iQres = i1.Qres:iN.Qres;

%% ===================== Constraints: reactive reserve =====================
% (1) Generator coupling: Qg_pu + Qres_pu <= Qmax_pu
Qmax_pu = mpc.gen(:, QMAX) / baseMVA;
A_qres = sparse(ng, nv);
for k = 1:ng
    A_qres(k, iQg(k))   = 1;
    A_qres(k, iQres(k)) = 1;
end
l_qres = -inf(ng, 1);
u_qres = Qmax_pu;
om.add_lin_constraint('qres_cap', A_qres, l_qres, u_qres);

% (2) System requirement: sum(Qres) >= 10% of total active load
Pd_total_MW = sum(mpc.bus(:, PD));
Qres_req_MVAr = 0.10 * Pd_total_MW;
Qres_req_pu = Qres_req_MVAr / baseMVA;

A_req = sparse(1, nv);
A_req(1, iQres) = 1;
l_req = Qres_req_pu;
u_req = inf;
om.add_lin_constraint('req_Qres', A_req, l_req, u_req);

%% ===================== Objective add-on: reactive reserve incentive =====================
% Add linear term: w * Qres (w < 0 encourages larger reserve)
w_MVAr = -5;                 % cost per MVAr of reserve (linear)
w_pu   = w_MVAr * baseMVA;    % because Qres_pu * baseMVA = Qres_MVAr

c = zeros(nv, 1);
c(iQres) = w_pu * ones(ng, 1);
Q = sparse(nv, nv);
k0 = 0;
om.add_quad_cost('qreserve_cost', Q, c, k0);

%% ===================== Emission cap constraint =====================
% Define emission factors (tCO2/MWh). If ng > 3, assign cyclically.
e_base = [0.9; 0.5; 0.0];
e_t_per_MWh = e_base(mod((1:ng)'-1, numel(e_base)) + 1);

Cap_t_per_h = 140;
Allowance_t_per_h = 0;
cap_total = Cap_t_per_h + Allowance_t_per_h;

% Pg variable is p.u., so MW = Pg_pu * baseMVA
% Emission (t/h) = sum e_i * Pg_MW = sum e_i * baseMVA * Pg_pu
A_emis = sparse(1, nv);
A_emis(1, iPg) = (e_t_per_MWh(:)' * baseMVA);

l_emis = -inf;
u_emis = cap_total;
om.add_lin_constraint('emission_cap_CO2', A_emis, l_emis, u_emis);

%% ===================== Solve =====================
[x, f, eflag, output, lambda] = om.solve();
if eflag <= 0
    error('OPF failed to converge (eflag=%d).', eflag);
end

%% ===================== Extract results =====================
Pg_MW   = x(iPg)   * baseMVA;
Qg_MVAr = x(iQg)   * baseMVA;
Qres_MVAr = x(iQres) * baseMVA;

emission_t_per_h = sum(e_t_per_MWh .* Pg_MW);

fprintf('\n===== AC OPF with Reactive Reserve + Emission Cap (case33mg) =====\n');
fprintf('Objective f = %.6f\n', f);
fprintf('Total load Pd = %.3f MW\n', Pd_total_MW);
fprintf('Reactive reserve requirement = %.3f MVAr\n', Qres_req_MVAr);
fprintf('Total reactive reserve provided = %.3f MVAr\n', sum(Qres_MVAr));
fprintf('Total emission = %.4f t/h, Cap = %.4f t/h, Margin = %.4f t/h\n', ...
    emission_t_per_h, cap_total, cap_total - emission_t_per_h);

T = table((1:ng)', Pg_MW, Qg_MVAr, Qres_MVAr, e_t_per_MWh, e_t_per_MWh .* Pg_MW, ...
    'VariableNames', {'Gen','Pg_MW','Qg_MVAr','Qres_MVAr','e_t_per_MWh','Emission_t_per_h'});
disp(T);

% Pack a results struct (optional)
results = mpc;
results.success = (eflag > 0);
results.f = f;
results.gen(:, PG) = Pg_MW;
results.gen(:, QG) = Qg_MVAr;
results.userdata.Qres_MVAr = Qres_MVAr;
results.userdata.emission_t_per_h = emission_t_per_h;
results.userdata.emission_cap_t_per_h = cap_total;

define_constants;

%% =============== User options (from OTS template style) ===============
useropt = struct();
useropt.casename   = 'case22';
useropt.model      = 'DC';          % DC network model for OTS
useropt.solver     = 'OT';          % OTS DC solver hook (per template)
useropt.M          = 1e5;           % big-M
useropt.GUB        = 4;             % max number of opened lines
useropt.heuristic  = 'basic';
useropt.MaxTime    = 600;
useropt.MaxNodes   = 5e5;

%% =============== Load case and apply base parameter modifications ===============
mpc = loadcase(useropt.casename);

% (1) Bus 8, QD: scale to 0
mpc.bus(8, QD) = 0;

% (2) Generator at bus 1, QMIN: set to -50
ig1 = find(mpc.gen(:, GEN_BUS) == 1);
if isempty(ig1)
    error('No generator found at bus 1.');
end
mpc.gen(ig1(1), QMIN) = -50;

% (3) Branch (11->19), BR_R: scale to 2
ibr = find(mpc.branch(:, F_BUS) == 11 & mpc.branch(:, T_BUS) == 19);
if isempty(ibr)
    error('Branch 11->19 not found in case.');
end
mpc.branch(ibr(1), BR_R) = 2 * mpc.branch(ibr(1), BR_R);

% (4) Branch (22->1), BR_B: scale to 1.1
ibr2 = find(mpc.branch(:, F_BUS) == 22 & mpc.branch(:, T_BUS) == 1);
if isempty(ibr2)
    error('Branch 22->1 not found in case.');
end
mpc.branch(ibr2(1), BR_B) = 1.1 * mpc.branch(ibr2(1), BR_B);

%% =============== Options / solver requirements ===============
mpopt = mpoption('model', useropt.model, 'verbose', 2, 'out.all', 0);
mpopt = mpoption(mpopt, 'opf.dc.solver', useropt.solver);
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);

%% =============== Build OPF model ===============
mpc = ext2int(mpc, mpopt);
om  = opf_setup(mpc, mpopt);

[baseMVA, bus, gen, branch] = deal(mpc.baseMVA, mpc.bus, mpc.gen, mpc.branch);
[nb, ng, nl] = deal(size(bus,1), size(gen,1), size(branch,1));

%% ---- OTS structural modifications (from 2_OTS template) ----
% Relax/disable original power mismatch linear constraints bounds (will add our own)
om.set_params('lin', 'Pmis', {'l', 'u'}, {-Inf(om.getN('lin','Pmis'),1), Inf(om.getN('lin','Pmis'),1)});

% Add variables: Pf (continuous), Z (binary)
om.add_var('Pf', nl, zeros(nl,1));
om.add_var('Z',  nl, ones(nl,1), [], [], 'B');

% Build DC matrices
[B, Bf, Pbusinj, Pfinj] = makeBdc(baseMVA, bus, branch);
f = branch(:, F_BUS);
t = branch(:, T_BUS);

% Incidence for KCL with Pf
Cft = sparse([(1:nl)'; (1:nl)'], [f; t], [ones(nl,1); -ones(nl,1)], nl, nb);
neg_Cg = sparse(gen(:, GEN_BUS), 1:ng, -1, nb, ng);
A = [Cft' neg_Cg];
bmis = -(bus(:, PD) + bus(:, GS)) / baseMVA - Pbusinj;

Il  = speye(nl);
rhs = useropt.M * ones(nl, 1);

% Conditional line limits: -Pmax*Z <= Pf <= Pmax*Z
il = find(branch(:, RATE_A) ~= 0 & branch(:, RATE_A) < 1e10);
Pmax = inf(nl,1);
Pmin = inf(nl,1);
if ~isempty(il)
    Pmax(il) = branch(il, RATE_A) / baseMVA - Pfinj(il);
    Pmin(il) = branch(il, RATE_A) / baseMVA + Pfinj(il);
end

% Add linear constraints
om.add_lin_constraint('Pfl',   [Il,  diag(Pmin)], zeros(nl,1), [], {'Pf', 'Z'});      % Pf + Pmin*Z >= 0  -> Pf >= -Pmin*Z
om.add_lin_constraint('Pfu',   [Il, -diag(Pmax)], [], zeros(nl,1), {'Pf', 'Z'});      % Pf - Pmax*Z <= 0  -> Pf <=  Pmax*Z
om.add_lin_constraint('Pfmis', A, bmis, bmis, {'Pf', 'Pg'});                          % nodal balance
om.add_lin_constraint('Ml',    [Bf, -Il, -useropt.M*Il], -rhs, [], {'Va', 'Pf', 'Z'});% -M(1-Z) <= Bf*Va - Pf
om.add_lin_constraint('Mu',    [Bf, -Il,  useropt.M*Il], [], rhs, {'Va', 'Pf', 'Z'}); %  Bf*Va - Pf <=  M(1-Z)
om.add_lin_constraint('GUB',   ones(1, nl), nl-useropt.GUB, [], {'Z'});               % sum(Z) >= nl-GUB

%% ---- Objective modification: line-charging reactive power procurement cost proxy ----
% Build alpha from branch charging susceptance BR_B
r_ch = 10;                 % [$/Mvar] coefficient from template
alpha = zeros(nb, 1);
for k = 1:nl
    fb = branch(k, F_BUS);
    tb = branch(k, T_BUS);
    Bch = branch(k, BR_B);
    coeff = r_ch * abs(Bch) / 2;
    alpha(fb) = alpha(fb) + coeff;
    alpha(tb) = alpha(tb) + coeff;
end

% Add quadratic cost on Vm (note: Vm exists in the OPF model even in DC; it will be fixed at 1 p.u. unless freed)
idx   = om.var.idx;
idx_i1 = idx.i1;
idx_iN = idx.iN;
nv = om.var.N;

Q = sparse(nv, nv);
c = zeros(nv, 1);
k0 = 0;

if isfield(idx_i1, 'Vm') && idx_iN.Vm >= idx_i1.Vm
    Qvm = spdiags(2*alpha, 0, nb, nb);
    Q(idx_i1.Vm:idx_iN.Vm, idx_i1.Vm:idx_iN.Vm) = Qvm;
    om.add_quad_cost('Qch_cost', Q, c, k0);
else
    warning('Vm variable not present in the model; skipping Qch_cost term.');
end

%% =============== Solve as MIP ===============
opt = mpopt2qpopt(mpopt, om.problem_type());
opt.intlinprog_opt = struct('MaxTime', useropt.MaxTime, 'MaxNodes', useropt.MaxNodes, 'Heuristics', useropt.heuristic);

[result_ots, fval, eflag, output, lambda] = om.solve(opt);

%% =============== Pack results ===============
results = mpc;
results.success = (eflag > 0);
results.f = fval;

% Extract key variable solutions
idx = om.var.idx;
Va = result_ots(idx.i1.Va:idx.iN.Va);
Pg = result_ots(idx.i1.Pg:idx.iN.Pg);

results.bus(:, VA) = Va * 180/pi;
results.gen(:, PG) = Pg * baseMVA;

if isfield(idx.i1, 'Vm')
    Vm = result_ots(idx.i1.Vm:idx.iN.Vm);
    results.bus(:, VM) = Vm;
end

% Optional: compute Qch proxy cost value from Vm if present
if isfield(idx.i1, 'Vm')
    Vm = results.bus(:, VM);
    Qch_cost_value = sum(alpha .* (Vm.^2));
else
    Qch_cost_value = NaN;
end

fprintf('\nDCOTS finished. success = %d\n', results.success);
fprintf('Total objective (incl. added Qch proxy term if active) = %.6f\n', results.f);
if ~isnan(Qch_cost_value)
    fprintf('Added line-charging reactive power proxy cost = %.6f\n', Qch_cost_value);
end

define_constants;
