mpopt = mpoption(mpopt, 'opf.dc.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);

%% ==================== Objective modification (voltage deviation cost) ====================
% In DCOPF, Vm is not a decision variable (fixed at 1.0 p.u.).
% We include the requested voltage-deviation quadratic cost as a constant
% objective offset consistent with Vm = 1.0.

beta = 10000;
Vref_target = 1.0;
nb = size(mpc.bus, 1);

% Build OPF model for DC and add constant offset (equivalent to Vm fixed)
% Constant term: beta * sum((1 - Vref)^2)
Vm_fixed = ones(nb, 1);
Vref = Vref_target * ones(nb, 1);
k = beta * sum((Vm_fixed - Vref).^2);

% Use OPF model to add the constant cost term, then solve.
om = opf_setup(mpc, mpopt);

% Add a quadratic cost with zero Q and c, only constant k
nv = om.var.N;
Q = sparse(nv, nv);
c = zeros(nv, 1);
om.add_quad_cost('voltage_penalty', Q, c, k);

%% ==================== Solve ====================
[x, f, eflag, output, lambda] = om.solve();

%% ==================== Build results struct ====================
% Convert solution vector to MATPOWER results using opfcn callback
% (fallback: run rundcopf for a fully-populated results struct)

% Preferred: use runopf-like post-processing by calling opf_execute
% If not available in this MATPOWER version, fall back to rundcopf.
results = [];
try
    % opf_execute is available in many MATPOWER versions
    [results, success] = opf_execute(om, mpopt);
    results.success = success;
catch
    % Fallback: solve standard DCOPF to get a standard results struct
    % and then overwrite objective value with augmented f
    results = rundcopf(mpc, mpopt);
    results.f = f;
    results.success = (eflag > 0);
end

%% ==================== Reporting ====================
fprintf('Success: %d\n', results.success);
fprintf('Total objective (incl. voltage penalty term): %.6f\n', f);
if isfield(results, 'gen')
    fprintf('Total Pg (MW): %.6f\n', sum(results.gen(:, PG)));
end

define_constants;
clearvars -except BUS_I PD QD GS BS BUS_TYPE VM VA BASE_KV ZONE VMAX VMIN GEN_BUS PG QG QMAX QMIN VG MBASE GEN_STATUS PMAX PMIN MU_PMAX MU_PMIN MU_QMAX MU_QMIN PC1 PC2 QC1MIN QC1MAX QC2MIN QC2MAX RAMP_AGC RAMP_10 RAMP_30 RAMP_Q APF MODEL STARTUP SHUTDOWN NCOST COST C1 C2 C3 C4;
clc;

%% ======================== Load case =========================
mpc = loadcase('case51ga');

%% =================== Base parameter modifications ===================
% (1) Generator at bus 8: scale COST_PARAMS_C3 to 1, COST_PARAMS_C1 to 1.1
% MATPOWER gencost for polynomial: [MODEL STARTUP SHUTDOWN NCOST c(n-1) ... c0]
% Here: C3 = quadratic coefficient (for NCOST=3), C1 = constant term.
if ~isfield(mpc, 'gencost') || isempty(mpc.gencost)
    error('mpc.gencost is missing or empty.');
end

% find generator row(s) whose GEN_BUS == 8
ig8 = find(mpc.gen(:, GEN_BUS) == 8);
if isempty(ig8)
    error('No generator found at bus 8.');
end

for k = 1:numel(ig8)
    r = ig8(k);
    if mpc.gencost(r, MODEL) ~= POLYNOMIAL
        error('Generator cost model at bus 8 is not POLYNOMIAL.');
    end
    ncost = mpc.gencost(r, NCOST);
    % Indices of polynomial coefficients in gencost row:
    % coeffs are in columns (NCOST+1 .. NCOST+NCOST)?? Actually fixed layout:
    % columns: 1..4 are MODEL, STARTUP, SHUTDOWN, NCOST, then NCOST coeffs.
    % So coefficients start at col = 5.
    c0_col = 4 + ncost;      % constant term position if ordered [c_{n-1} ... c0]
    c2_col = 5;              % for ncost>=3, quadratic coefficient is first (c2)

    if ncost < 2
        error('Unexpected NCOST (%d) for generator at bus 8.', ncost);
    end

    % Scale C3 to 1x (i.e., leave unchanged) if quadratic exists
    if ncost >= 3
        mpc.gencost(r, c2_col) = 1.0 * mpc.gencost(r, c2_col);
    end

    % Scale C1 (constant term) to 1.1x
    mpc.gencost(r, c0_col) = 1.1 * mpc.gencost(r, c0_col);
end

% (2) Branch (5 -> 14): BR_STATUS = 1
br_5_14 = find(mpc.branch(:, F_BUS) == 5 & mpc.branch(:, T_BUS) == 14);
if isempty(br_5_14)
    warning('Branch (5->14) not found in mpc.branch; no BR_STATUS change applied.');
else
    mpc.branch(br_5_14, BR_STATUS) = 1;
end

% (3) Branch (43 -> 5): BR_X scaled by 1.2
br_43_5 = find(mpc.branch(:, F_BUS) == 43 & mpc.branch(:, T_BUS) == 5);
if isempty(br_43_5)
    warning('Branch (43->5) not found in mpc.branch; no BR_X scaling applied.');
else
    mpc.branch(br_43_5, BR_X) = 1.2 * mpc.branch(br_43_5, BR_X);
end

%% ======================== DCOPF + robust constraints =========================
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'DC');
mpopt = mpoption(mpopt, 'opf.dc.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);

% 1) Ensure RATE_A is meaningful (avoid zeros)
rateA = mpc.branch(:, RATE_A);
if all(rateA == 0)
    mpc.branch(:, RATE_A) = 250;
else
    mpc.branch(rateA == 0, RATE_A) = 1e4;
end

% 2) Uncertainty set U: choose uncertain buses and bounds (MW)
% (kept from template; adjust if desired)
unc_buses_ext = [5; 9];
Delta_MW      = [30; 20];

%% ======================== Build robust constraints via PTDF =========================
mpc_i   = ext2int(mpc);
baseMVA = mpc_i.baseMVA;
bus     = mpc_i.bus;
branch  = mpc_i.branch;
gen     = mpc_i.gen;

nb = size(bus, 1);
nl = size(branch, 1);
ng = size(gen, 1);

PTDF = makePTDF(baseMVA, bus, branch);   % nl x nb

% Bus injection mapping
Cg = sparse(gen(:, GEN_BUS), (1:ng)', 1, nb, ng);
Pd = bus(:, PD) / baseMVA;

% Map external uncertain bus numbers to internal indices based on the same modified case
unc_buses_int = zeros(size(unc_buses_ext));
for k = 1:numel(unc_buses_ext)
    bi = find(mpc_i.bus(:, BUS_I) == unc_buses_ext(k), 1);
    if isempty(bi)
        error('Uncertain bus ext #%d not found in case51ga after ext2int.', unc_buses_ext(k));
    end
    unc_buses_int(k) = bi;
end

Delta_pu = Delta_MW(:) / baseMVA;
PTDF_U = PTDF(:, unc_buses_int);
worst  = abs(PTDF_U) * Delta_pu;     % nl x 1 (p.u.)

Fmax = branch(:, RATE_A) / baseMVA;  % p.u.

% Build OPF model and add robust linear constraints
om = opf_setup(mpc_i, mpopt);
idx = om.var.idx;
i1 = idx.i1.Pg;
iN = idx.iN.Pg;
nv = om.var.N;

if (iN - i1 + 1) ~= ng
    error('Pg dimension mismatch between OM and case data.');
end

Arows = [];
lvec  = [];
uvec  = [];

for ell = 1:nl
    if branch(ell, BR_STATUS) == 0
        continue;
    end
    if Fmax(ell) <= 0
        continue;
    end

    margin = Fmax(ell) - worst(ell);

    % If margin is negative, constraints will likely make infeasible; keep them (explicitly robust)
    a_pg  = PTDF(ell,:) * Cg;      % 1 x ng
    cst   = PTDF(ell,:) * (-Pd);   % scalar

    % mu_f <= margin  => a_pg*Pg + cst <= margin => a_pg*Pg <= margin - cst
    rhs_pos = margin - cst;
    % -mu_f <= margin => -a_pg*Pg - cst <= margin => -a_pg*Pg <= margin + cst
    rhs_neg = margin + cst;

    Arows(end+1, :) =  a_pg; %#ok<SAGROW>
    lvec(end+1, 1)  = -Inf;
    uvec(end+1, 1)  =  rhs_pos;

    Arows(end+1, :) = -a_pg; %#ok<SAGROW>
    lvec(end+1, 1)  = -Inf;
    uvec(end+1, 1)  =  rhs_neg;
end

if ~isempty(Arows)
    A = sparse(Arows);
    Afull = sparse(size(A, 1), nv);
    Afull(:, i1:iN) = A;
    om = om.add_lin_constraint('ROBUST_LINE_LIMITS_BOX', Afull, lvec, uvec);
end

%% ==================== Solve and report ====================
try
    [res_i, success] = opf_execute(om, mpopt);
catch
    [res_i, success] = opf_execute(om, mpc_i, mpopt);
end

if ~success
    error('Robust DCOPF failed (likely infeasible under given uncertainty bounds).');
end

results = int2ext(res_i, mpc);

% Post-check: |mu_f| + worst <= Fmax
Pg_pu = res_i.gen(:, PG) / baseMVA;
mu_f  = PTDF * (Cg * Pg_pu - Pd);
lhs   = abs(mu_f) + worst;
viol  = max(lhs - Fmax, 0);

fprintf('\n=== Robust-DCOPF (case51ga, box uncertainty) summary ===\n');
fprintf('Uncertain buses (ext): %s\n', mat2str(unc_buses_ext(:)'));
fprintf('Delta (MW):           %s\n', mat2str(Delta_MW(:)'));
fprintf('Max violation:        %.6g p.u. (%.6g MW)\n', max(viol), max(viol)*baseMVA);
fprintf('Objective (total cost): %.6f\n', results.f);

