for k = 1:numel(unc_buses_ext)
    extno = unc_buses_ext(k);
    % Find row in external data
    row_ext = find(mpc0.bus(:, BUS_I) == extno, 1);
    if isempty(row_ext)
        error('Uncertain bus ext #%d not found in case118zh.', extno);
    end
    % After ext2int, the bus with external number extno is located where BUS_I == extno
    row_int = find(mpc0_i.bus(:, BUS_I) == extno, 1);
    if isempty(row_int)
        error('Uncertain bus ext #%d not found after ext2int mapping.', extno);
    end
    unc_buses_int(k) = row_int;
end

Delta_pu = Delta_MW(:) / baseMVA;

% Worst-case flow deviation margin per line: worst(l) = sum_j |PTDF(l,bj)|*Delta_j
PTDF_U = PTDF(:, unc_buses_int);
worst  = abs(PTDF_U) * Delta_pu;   % nl x 1 (p.u.)

Fmax = branch(:, RATE_A) / baseMVA; % p.u.

% Build OPF model and add robust linear constraints on Pg
om = opf_setup(mpc_i, mpopt);

idx = om.var.idx;
i1 = idx.i1.Pg;
iN = idx.iN.Pg;
nv = om.var.N;

if (iN - i1 + 1) ~= ng
    error('Pg dimension mismatch: OM has %d Pg vars, case has %d gens.', (iN - i1 + 1), ng);
end

Arows = [];
lvec  = [];
uvec  = [];

for ell = 1:nl
    if branch(ell, BR_STATUS) == 0
        continue;
    end
    if Fmax(ell) <= 0
        continue;
    end

    margin = Fmax(ell) - worst(ell);

    % mu_f_l = PTDF(l,:)*(Cg*Pg - Pd)
    a_pg  = PTDF(ell,:) * Cg;     % 1 x ng
    cst   = PTDF(ell,:) * (-Pd);  % scalar

    % mu_f <= margin  => a_pg*Pg + cst <= margin => a_pg*Pg <= margin - cst
    rhs_pos = margin - cst;
    % -mu_f <= margin => -a_pg*Pg - cst <= margin => -a_pg*Pg <= margin + cst
    rhs_neg = margin + cst;

    Arows(end+1, :) =  a_pg; %#ok<SAGROW>
    lvec(end+1, 1)  = -Inf;
    uvec(end+1, 1)  =  rhs_pos;

    Arows(end+1, :) = -a_pg; %#ok<SAGROW>
    lvec(end+1, 1)  = -Inf;
    uvec(end+1, 1)  =  rhs_neg;
end

if ~isempty(Arows)
    A = sparse(Arows);
    Afull = sparse(size(A,1), nv);
    Afull(:, i1:iN) = A;
    om = om.add_lin_constraint('ROBUST_LINE_LIMITS_BOX', Afull, lvec, uvec);
end

%% ===================== Solve =====================
try
    [res_i, success] = opf_execute(om, mpopt);
catch
    [res_i, success] = opf_execute(om, mpc_i, mpopt);
end

if ~success
    error('Robust DCOPF failed (likely infeasible under given uncertainty bounds).');
end

results = int2ext(res_i, mpc);

%% ===================== Post-check robust constraint =====================
% Verify: |mu_f| + worst <= Fmax
mpc_i_res = res_i;
Pg_pu = mpc_i_res.gen(:, PG) / baseMVA;
mu_f  = PTDF * (Cg*Pg_pu - Pd);
lhs   = abs(mu_f) + worst;
viol  = max(lhs - Fmax, 0);

fprintf('\n=== Robust-DCOPF (box) summary ===\n');
fprintf('Case:            %s\n', 'case118zh');
fprintf('unc buses (ext):  %s\n', mat2str(unc_buses_ext(:)'));
fprintf('Delta (MW):       %s\n', mat2str(Delta_MW(:)'));
fprintf('Max violation:    %.6g p.u. (%.6g MW)\n', max(viol), max(viol) * baseMVA);
fprintf('Objective:        %.6f\n', results.f);

