%% ==================== MOST user function factory ====================
function ufn = most_userfcn_emis_softlims(lambda_slack, e_t_per_MWh_user, Cap_t_per_h, Allowance_t_per_h)
% Returns a MOST userfcn struct that adds:
%  (1) soft line limits via nonnegative slack vars + linear penalty cost
%  (2) per-period CO2 emission cap: e' * Pg <= cap

ufn = struct();
ufn.name = 'most_emis_softlims';
ufn.int2ext = '';
ufn.ext2int = '';
ufn.formulation = @formulation_cb;
ufn.printpf = '';
ufn.savecase = '';

    function mdo = formulation_cb(mdo)
        define_constants;

        % Access MOST model object
        om = mdo.om;
        mpc = mdo.mpc;

        ng = size(mpc.gen, 1);
        nl = size(mpc.branch, 1);

        % ---------- (A) Soft line limits ----------
        % For DC, we soften |Pf| and |Pt| against RATE_A using linear slacks.
        % If RATE_A is 0, substitute a default.
        rate_a = mpc.branch(:, RATE_A);
        rate_a(rate_a == 0) = 250;

        % Add nonnegative slack variables for each period
        % MOST uses indexed variable blocks with a time dimension. We add
        % slacks as 'mpc' variables via OM as a t x nl block.
        % Lower bounds 0, upper bounds inf.
        nt = mdo.idx.nt;
        om.add_var('s_from', nl, zeros(nl,1), zeros(nl,1), inf(nl,1), {'T', nt});
        om.add_var('s_to',   nl, zeros(nl,1), zeros(nl,1), inf(nl,1), {'T', nt});

        % Add linear cost: lambda_slack * sum(slacks) each period
        % Implement as a linear cost term on these variables.
        % In OM, a linear cost can be represented via add_quad_cost with Q=0.
        idx = om.get_idx();
        nv = om.var.N;
        c = zeros(nv, 1);
        % s_from and s_to have time indexing; idx gives i1/iN per block.
        % MOST stores time-expanded blocks; we take full index ranges.
        isf = idx.i1.s_from : idx.iN.s_from;
        ist = idx.i1.s_to   : idx.iN.s_to;
        c(isf) = lambda_slack;
        c(ist) = lambda_slack;
        om.add_quad_cost('soft_line_limit_penalty', sparse(nv,nv), c, 0);

        % Add soft flow limit constraints per period:
        %   Pf <= rate_a + s_from
        %  -Pf <= rate_a + s_from
        % similarly for Pt with s_to.
        % Use DC branch flow sensitivity from MOST internal PTDF matrices if available;
        % otherwise build Bf*Va mapping from makeBdc.
        baseMVA = mpc.baseMVA;
        [Bbus, Bf, ~, ~] = makeBdc(baseMVA, mpc.bus, mpc.branch);

        % Get angle variable indices (time-expanded)
        iVa = idx.i1.Va : idx.iN.Va;

        % Build time-blocked constraints: for each t,
        % Pf_t = Bf * Va_t * baseMVA (in MW)
        % Here Va is in radians.
        % We assemble A*x <= u form with x = [Va_all; ...; slacks ...].
        % Dimensions:
        %   Va_all length = nb*nt
        %   s_from_all length = nl*nt
        % We'll create constraints using sparse matrices.
        nb = size(mpc.bus, 1);

        % Indices for time-expanded blocks in decision vector
        is_from = idx.i1.s_from : idx.iN.s_from;
        is_to   = idx.i1.s_to   : idx.iN.s_to;

        % Preallocate sparse pattern
        ncon = 4 * nl * nt;
        A = sparse(ncon, nv);
        l = -inf(ncon, 1);
        u = zeros(ncon, 1);

        row = 0;
        for t = 1:nt
            % variable sub-indices for Va at time t
            va_t = iVa((t-1)*nb + (1:nb));
            sf_t = is_from((t-1)*nl + (1:nl));
            st_t = is_to((t-1)*nl + (1:nl));

            % Pf = Bf * Va * baseMVA
            % 1) Pf - sf <= rate
            rr = row + (1:nl);
            A(rr, va_t) =  (Bf * baseMVA);
            A(rr, sf_t) = -speye(nl);
            u(rr) = rate_a;
            row = row + nl;

            % 2) -Pf - sf <= rate
            rr = row + (1:nl);
            A(rr, va_t) = -(Bf * baseMVA);
            A(rr, sf_t) = -speye(nl);
            u(rr) = rate_a;
            row = row + nl;

            % For DC, Pt = -Pf (ignoring losses). Use same mapping.
            % 3) Pt - st <= rate  => (-Pf) - st <= rate
            rr = row + (1:nl);
            A(rr, va_t) = -(Bf * baseMVA);
            A(rr, st_t) = -speye(nl);
            u(rr) = rate_a;
            row = row + nl;

            % 4) -Pt - st <= rate => (Pf) - st <= rate
            rr = row + (1:nl);
            A(rr, va_t) =  (Bf * baseMVA);
            A(rr, st_t) = -speye(nl);
            u(rr) = rate_a;
            row = row + nl;
        end

        om.add_lin_constraint('soft_dc_branch_limits', A, l, u);

        % ---------- (B) Emission cap per period ----------
        % Align emission vector length to ng
        e = e_t_per_MWh_user(:);
        if numel(e) < ng
            e = [e; zeros(ng-numel(e), 1)];
        elseif numel(e) > ng
            e = e(1:ng);
        end
        cap_total = Cap_t_per_h + Allowance_t_per_h;

        % Pg is in p.u. inside OM; Pg_MW = Pg_pu * baseMVA
        % For each time t: sum_i e_i * (Pg_pu_i * baseMVA) <= cap
        iPg = idx.i1.Pg : idx.iN.Pg;

        % Build per-time constraints: (e'*baseMVA) * Pg_t <= cap
        Aem = sparse(nt, nv);
        uem = cap_total * ones(nt, 1);
        lem = -inf(nt, 1);
        for t = 1:nt
            pg_t = iPg((t-1)*ng + (1:ng));
            Aem(t, pg_t) = (e' * baseMVA);
        end
        om.add_lin_constraint('emission_cap_CO2', Aem, lem, uem);

        % Write back OM
        mdo.om = om;
    end
end

