%% ========= Local function: MOST userfcn to add angle-difference penalty =========
function mdo = most_add_angdiff_pen(mdo, mpopt)
    define_constants;
    beta = 10; %#ok<NASGU>

    % Build E from the (base) network in the MOST data (same topology each period)
    mpc0 = mdo.mdi.mpc;
    nb = size(mpc0.bus, 1);
    nl = size(mpc0.branch, 1);
    fbus = mpc0.branch(:, F_BUS);
    tbus = mpc0.branch(:, T_BUS);
    E = sparse(1:nl, fbus,  1, nl, nb) + sparse(1:nl, tbus, -1, nl, nb);
    Qva = 2 * 10 * (E' * E);   % 0.5*x'*Q*x equals beta*||E*Va||^2

    % Add per-period quadratic cost on Va
    % MOST stores a separate OM per time period in mdo.om (cell array)
    if iscell(mdo.om)
        nt = numel(mdo.om);
        for t = 1:nt
            try
                mdo.om{t} = mdo.om{t}.add_quad_cost(sprintf('ang_diff_pen_t%02d', t), Qva, [], 0, {'Va'});
            catch me
                error('Failed to add angle-difference penalty in period %d: %s', t, me.message);
            end
        end
    else
        % Fallback for implementations where OM is not a cell
        try
            mdo.om = mdo.om.add_quad_cost('ang_diff_pen', Qva, [], 0, {'Va'});
        catch me
            error('Failed to add angle-difference penalty: %s', me.message);
        end
    end
end

