mpc.bus(b20, QD) = 1.2 * mpc.bus(b20, QD);

% - Generator at bus 3, COST_PARAMS_C2: Scale to 0.9
%   Assumes polynomial cost model with gencost columns: [MODEL STARTUP SHUTDOWN NCOST c(n-1) ... c0]
%   For quadratic (NCOST=3): gencost(:, 5:7) = [c2 c1 c0]
idx_g3 = find(mpc.gen(:, GEN_BUS) == 3);
if isempty(idx_g3)
    error('No generator found at bus 3');
end
for k = 1:length(idx_g3)
    g = idx_g3(k);
    if mpc.gencost(g, MODEL) ~= 2
        error('Generator %d at bus 3 does not use polynomial cost model (MODEL=2).', g);
    end
    ncost = mpc.gencost(g, NCOST);
    if ncost < 3
        error('Generator %d at bus 3 does not have a quadratic term (NCOST < 3).', g);
    end
    % quadratic coefficient is the first cost coefficient at column 5
    mpc.gencost(g, COST) = 0.9 * mpc.gencost(g, COST);
end

%% =====================
%% 3) Economy dispatch QP setup (no network constraints)
%% =====================
% Total active load (MW)
Pd_total = sum(mpc.bus(:, PD));

% Consider only online generators
on = find(mpc.gen(:, GEN_STATUS) > 0);
ng = length(on);
if ng == 0
    error('No online generators found.');
end

Pmin = mpc.gen(on, PMIN);
Pmax = mpc.gen(on, PMAX);

% Extract quadratic cost coefficients for each online generator
% Require quadratic polynomial costs (NCOST=3) for simplicity/consistency with template
c2 = zeros(ng,1);
c1 = zeros(ng,1);
c0 = zeros(ng,1);
for ii = 1:ng
    gi = on(ii);
    if mpc.gencost(gi, MODEL) ~= 2
        error('gencost row %d is not polynomial (MODEL=2).', gi);
    end
    if mpc.gencost(gi, NCOST) ~= 3
        error('This template expects quadratic costs with NCOST=3. Row %d has NCOST=%d.', gi, mpc.gencost(gi, NCOST));
    end
    c2(ii) = mpc.gencost(gi, 5);
    c1(ii) = mpc.gencost(gi, 6);
    c0(ii) = mpc.gencost(gi, 7);
end

% QP: min 0.5*x'*H*x + f'*x  s.t. Aeq*x=beq, lb<=x<=ub, A*x<=b
H = 2 * diag(c2);      % so that 0.5*x'*H*x = sum c2*Pg^2
f = c1;

Aeq = ones(1, ng);
beq = Pd_total;

lb = Pmin;
ub = Pmax;

%% =====================
%% 4) Add emissions cap constraint (linear inequality)
%% =====================
% User-specified emissions intensity for each online generator (tCO2/MWh)
% If you have real data, replace the construction below.
% Here: default all thermal-like units at 0.6 t/MWh (placeholder), can be edited.
e_t_per_MWh = 0.6 * ones(ng,1);

% Emission cap (tCO2/h). Choose a finite cap to make constraint active.
% If you want it inactive, set a very large value.
Cap_t_per_h = 1.0e6;

A = e_t_per_MWh(:)';
b = Cap_t_per_h;

%% =====================
%% 5) Solve QP (quadprog)
%% =====================
% Solver/feasibility tolerance requirement (analogous to opf_violation=1e-7)
mpopt = mpoption('opf.violation', 1e-7, 'verbose', 0, 'out.all', 0);

o = optimoptions('quadprog', ...
    'Display', 'none', ...
    'ConstraintTolerance', 1e-7, ...
    'OptimalityTolerance', 1e-7);

[Pg_MW, fval, exitflag, output, lambda] = quadprog(H, f, A, b, Aeq, beq, lb, ub, [], o);

if exitflag <= 0
    error('quadprog failed (exitflag=%d). Message: %s', exitflag, output.message);
end

total_cost = 0.5 * Pg_MW' * H * Pg_MW + f' * Pg_MW + sum(c0);

total_emission_t_per_h = sum(e_t_per_MWh .* Pg_MW);

%% =====================
%% 6) Report
%% =====================
fprintf('=== Economy Dispatch (QP) on %s ===\n', mpc.version);
fprintf('Total Pd = %.6f MW\n', Pd_total);
fprintf('Total cost = %.6f\n', total_cost);
fprintf('Total emission = %.6f t/h, Cap = %.6f t/h, Margin = %.6f t/h\n', ...
    total_emission_t_per_h, Cap_t_per_h, Cap_t_per_h - total_emission_t_per_h);

T = table(on, mpc.gen(on, GEN_BUS), Pg_MW, Pmin, Pmax, e_t_per_MWh, e_t_per_MWh .* Pg_MW, ...
    'VariableNames', {'GenRow','Bus','Pg_MW','Pmin_MW','Pmax_MW','e_t_per_MWh','Emission_t_per_h'});
disp(T);

