%% ==================== Nonlinear cost callback ====================
function [f, df, d2f] = loadability_cost_fcn(x, lambda_load, mpc, idx_i1, idx_iN, nv, rate_a)
    define_constants;

    Va = x(idx_i1.Va:idx_iN.Va);
    Vm = x(idx_i1.Vm:idx_iN.Vm);

    nl = size(mpc.branch, 1);

    % Build branch admittance matrices
    [~, Yf, Yt] = makeYbus(mpc.baseMVA, mpc.bus, mpc.branch);

    V = Vm .* exp(1j * Va);

    fbus = mpc.branch(:, F_BUS);
    tbus = mpc.branch(:, T_BUS);

    Sf = V(fbus) .* conj(Yf * V) * mpc.baseMVA;
    St = V(tbus) .* conj(Yt * V) * mpc.baseMVA;

    S_line = 0.5 * (abs(Sf) + abs(St));

    f = lambda_load * (1/nl) * sum(S_line ./ rate_a);

    % Finite-difference gradient (simple, general, but potentially slow)
    if nargout > 1
        eps_fd = 1e-7;
        df = zeros(nv, 1);
        for k = 1:nv
            x2 = x;
            x2(k) = x2(k) + eps_fd;
            f2 = loadability_cost_fcn(x2, lambda_load, mpc, idx_i1, idx_iN, nv, rate_a);
            df(k) = (f2 - f) / eps_fd;
        end
    end

    % Provide empty Hessian; solver may approximate
    if nargout > 2
        d2f = sparse(nv, nv);
    end
end

