    end
end

%% ========================
%% 2) MOST multi-period setup (DC model)
%% ========================
% MOST options (DC)
mpopt = mpoption(...
    'most.dc_model', 1, ...
    'model', 'DC', ...
    'opf.dc.solver', 'MIPS', ...
