%% 3) Add chance constraints on branch limits (per-period) via MOST userfcn
%% ========================
% Chance-constraint settings (single wind uncertainty source)
cc = struct();
cc.w_bus_ext   = mpc1.gen(iwind(1), GEN_BUS);  % use wind bus from addwind (external numbering)
cc.mu_w_MW     = 0;      % mean already embedded via profiles/most; set 0 here for margin-only
