% ---- helper: z without Stats Toolbox ----
function z = norminv_approx(p)
% Compute z = Phi^{-1}(p) without requiring Statistics Toolbox.
% Phi^{-1}(p) = -sqrt(2) * erfcinv(2p)
z = -sqrt(2) * erfcinv(2*p);
end

%% ========================================================================
%% MOST userfcn: add chance constraints to each period OM
%% ========================================================================
function om = most_userfcn_chance_line_limits(stage, om, mpopt, args)
% Adds per-period linear constraints enforcing:
%   |mu_f| + z*sigma_f <= Fmax
% under DC PTDF mapping with one uncertainty source at w_bus_ext.

define_constants;

if ~strcmp(stage, 'formulation')
    return;
end

cc = args; %#ok<NASGU>
cc = args; % struct with fields: w_bus_ext, sigma_w_MW, z

% Retrieve mpc for this time period from MOST OM
mpc = om.get_mpc();

% Convert to internal indexing for PTDF matrices
mpc_i = ext2int(mpc);
baseMVA = mpc_i.baseMVA;
bus     = mpc_i.bus;
branch  = mpc_i.branch;
gen     = mpc_i.gen;

nb = size(bus, 1);
nl = size(branch, 1);
ng = size(gen, 1);

% PTDF matrix (nl x nb)
PTDF = makePTDF(baseMVA, bus, branch);

% Generator-to-bus incidence (nb x ng)
Cg = sparse(gen(:, GEN_BUS), (1:ng)', 1, nb, ng);

% Demand vector (p.u.)
Pd = bus(:, PD) / baseMVA;

% Map external wind bus to internal index for this period
% (Use ext2int mapping by searching internal bus table for BUS_I=external id)
w_bus_int = find(bus(:, BUS_I) == cc.w_bus_ext, 1);
if isempty(w_bus_int)
    error('Chance constraint wind bus %d not found in internal bus numbering.', cc.w_bus_ext);
end

sigma_w_pu = cc.sigma_w_MW / baseMVA;
ptdf_w  = PTDF(:, w_bus_int);       % (nl x 1)
sigma_f = abs(ptdf_w) * sigma_w_pu; % (nl x 1)

% Line limits (p.u.)
Fmax = branch(:, RATE_A) / baseMVA;

% OM variable indexing for Pg
idx = om.var.idx;
i1 = idx.i1.Pg;
iN = idx.iN.Pg;
if (iN - i1 + 1) ~= ng
    error('Pg dimension mismatch in OM.');
end
nv = om.var.N;

Arows = [];
lb = [];
ub = [];

for ell = 1:nl
    if branch(ell, BR_STATUS) == 0
        continue;
    end

    a_pg  = PTDF(ell, :) * Cg;     % 1 x ng
    const = PTDF(ell, :) * (-Pd);  % scalar

    margin = Fmax(ell) - cc.z * sigma_f(ell);

    % mu_f <= margin  -> a_pg*Pg + const <= margin -> a_pg*Pg <= margin - const
    Arows(end+1, :) = a_pg; %#ok<AGROW>
    lb(end+1, 1)    = -Inf; %#ok<AGROW>
    ub(end+1, 1)    = margin - const; %#ok<AGROW>

    % -mu_f <= margin -> -a_pg*Pg - const <= margin -> -a_pg*Pg <= margin + const
    Arows(end+1, :) = -a_pg; %#ok<AGROW>
    lb(end+1, 1)    = -Inf; %#ok<AGROW>
    ub(end+1, 1)    = margin + const; %#ok<AGROW>
end

if ~isempty(Arows)
    A = sparse(Arows);
    Afull = sparse(size(A, 1), nv);
    Afull(:, i1:iN) = A;
    om = om.add_lin_constraint('CHANCE_LINE_LIMITS', Afull, lb, ub);
end

end

