%% ==================== Nonlinear constraint function ====================
function [h, dh] = branch_flow_soft_constraint(x, mpc, idx_i1, idx_iN, rate_a)
    define_constants;

    Va = x(idx_i1.Va:idx_iN.Va);
    Vm = x(idx_i1.Vm:idx_iN.Vm);
    s_from = x(idx_i1.s_from:idx_iN.s_from);
    s_to   = x(idx_i1.s_to:idx_iN.s_to);

    nl = size(mpc.branch, 1);
    nv = length(x);

    [~, Yf, Yt] = makeYbus(mpc.baseMVA, mpc.bus, mpc.branch);

    V = Vm .* exp(1j * Va);
    f_bus = mpc.branch(:, F_BUS);
    t_bus = mpc.branch(:, T_BUS);

    Sf = V(f_bus) .* conj(Yf * V) * mpc.baseMVA;
    St = V(t_bus) .* conj(Yt * V) * mpc.baseMVA;

    Sf_mag = abs(Sf);
    St_mag = abs(St);

    % h(x) <= 0
    h = [Sf_mag - rate_a - s_from;
         St_mag - rate_a - s_to];

    % Finite-difference Jacobian (simple but expensive)
    if nargout > 1
        eps_fd = 1e-7;
        dh = zeros(2*nl, nv);
        for k = 1:nv
            xp = x;
            xp(k) = xp(k) + eps_fd;
            hp = branch_flow_soft_constraint(xp, mpc, idx_i1, idx_iN, rate_a);
            dh(:, k) = (hp - h) / eps_fd;
        end
    end
end

define_constants;
clearvars -except; clc;

%% Load base case
mpc = loadcase('case94pi');

%% Parameter modifications (apply exactly as specified)
% - Bus 47, VMIN: Set to 0.99
