% - Bus 6, VMAX: Scale to 1.02
mpc.bus(6, VMAX) = 1.02 * mpc.bus(6, VMAX);

% - Bus 38, QD: Scale to 0
mpc.bus(38, QD) = 0 * mpc.bus(38, QD);

%% Economy Dispatch (QP) formulation
% Total real demand (MW)
Pd_total = sum(mpc.bus(:, PD));

% Consider only in-service generators
on = find(mpc.gen(:, GEN_STATUS) > 0);
ng = numel(on);

Pmin = mpc.gen(on, PMIN);
Pmax = mpc.gen(on, PMAX);

% Build quadratic cost coefficients for each online generator
% Expect polynomial cost model: gencost(:, MODEL)=POLYNOMIAL (2), NCOST=3 (quadratic)
if size(mpc.gencost, 1) < max(on)
    error('gencost does not have enough rows to match generators.');
end

gc = mpc.gencost(on, :);

% Validate polynomial quadratic form
if any(gc(:, MODEL) ~= POLYNOMIAL)
    error('This ED template assumes polynomial generator costs (MODEL=POLYNOMIAL).');
end
if any(gc(:, NCOST) < 2)
    error('This ED template requires at least linear polynomial costs (NCOST>=2).');
end

% Extract coefficients for quadratic cost: f(Pg)=c2*Pg^2 + c1*Pg + c0
% For NCOST=3, coefficients are in last 3 columns: [c2 c1 c0]
% For NCOST=2, treat as linear: [c1 c0]
C = zeros(ng, 3);  % [c2 c1 c0]
for k = 1:ng
    ncost = gc(k, NCOST);
    coeff = gc(k, end-ncost+1:end);
    if ncost == 3
        C(k, :) = coeff;
    elseif ncost == 2
        C(k, :) = [0, coeff(1), coeff(2)];
    else
        % If higher order, keep only quadratic+linear+constant from the last 3 terms
        % (common MATPOWER cases are quadratic; this is a safe fallback)
        C(k, :) = coeff(end-2:end);
    end
end

c2 = C(:, 1);
c1 = C(:, 2);
c0 = C(:, 3);

% QP matrices for quadprog: minimize 1/2 x' H x + f' x
H = 2 * diag(c2);
f = c1;

% Power balance constraint: sum Pg = Pd_total
Aeq = ones(1, ng);
beq = Pd_total;

lb = Pmin;
ub = Pmax;

%% Solve QP with tight constraint tolerance (opf_violation ~ 1e-7)
% Map opf_violation to QP constraint tolerance.
opts = optimoptions('quadprog', ...
    'Display', 'off', ...
    'ConstraintTolerance', 1e-7, ...
    'OptimalityTolerance', 1e-9, ...
    'StepTolerance', 1e-12);

[Pg, fval, exitflag, output] = quadprog(H, f, [], [], Aeq, beq, lb, ub, [], opts);

if exitflag <= 0
    error('ED QP did not converge (exitflag=%d). Message: %s', exitflag, output.message);
end

% Total cost (quadratic + linear + constant)
total_cost = sum(c2 .* (Pg.^2) + c1 .* Pg + c0);

%% Report results
fprintf('=== Economy Dispatch on case94pi (QP) ===\n');
fprintf('Total demand (MW): %.6f\n', Pd_total);
fprintf('Total generation (MW): %.6f\n', sum(Pg));
fprintf('Power balance residual (MW): %.6e\n', sum(Pg) - Pd_total);
fprintf('Total production cost: %.6f\n', total_cost);

fprintf('\nGenerator dispatch (online units):\n');
T = table(on, mpc.gen(on, GEN_BUS), Pg, Pmin, Pmax, ...
    'VariableNames', {'gen_index','bus','Pg_MW','Pmin_MW','Pmax_MW'});
disp(T);

