clear; clc;

%% ===================== Load case =====================
mpc0 = loadcase('case6ww');
mpc  = mpc0;

%% ===================== Base parameter modifications =====================
% (1) Generator at bus 3: set PMIN to 0
bus3 = 3;
g_idx = find(mpc.gen(:, GEN_BUS) == bus3);
if isempty(g_idx)
    error('No generator found at bus %d.', bus3);
end
mpc.gen(g_idx, PMIN) = 0;

% (2) Branch (6 -> 4): scale BR_B by 1.1
fbus = 6; tbus = 4;
br_idx = find(mpc.branch(:, F_BUS) == fbus & mpc.branch(:, T_BUS) == tbus);
if isempty(br_idx)
    error('No branch found with from-bus %d to-bus %d.', fbus, tbus);
end
mpc.branch(br_idx, BR_B) = 1.1 * mpc.branch(br_idx, BR_B);

%% ===================== Solver / OPF options =====================
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'DC');
mpopt = mpoption(mpopt, 'opf.dc.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);

%% ===================== Robust DC line limits (box uncertainty) =====================
% If RATE_A is 0, set to a large value (avoid meaningless binding constraints)
rateA = mpc.branch(:, RATE_A);
if all(rateA == 0)
    mpc.branch(:, RATE_A) = 250;   % fallback default
else
    mpc.branch(rateA == 0, RATE_A) = 1e4;
end

% ---- Uncertainty specification (can be adjusted) ----
% Uncertain net injections xi at these buses (external numbering), xi_k in [-Delta_k, +Delta_k] MW
% NOTE: Choose buses that exist in case6ww.
unc_buses_ext = [5; 6];
Delta_MW      = [10; 10];

% Convert to internal numbering for PTDF construction
mpc_i   = ext2int(mpc);
baseMVA = mpc_i.baseMVA;
bus     = mpc_i.bus;
branch  = mpc_i.branch;
gen     = mpc_i.gen;

nb = size(bus, 1);
nl = size(branch, 1);
ng = size(gen, 1);

% PTDF (nl x nb)
PTDF = makePTDF(baseMVA, bus, branch);

% Generator-to-bus incidence Cg, so injections are Cg*Pg - Pd
Cg = sparse(gen(:, GEN_BUS), (1:ng)', 1, nb, ng);
Pd = bus(:, PD) / baseMVA;   % p.u.

% Map external uncertain buses to internal indices
% Use original external case for consistent mapping
mpc_map = ext2int(mpc);
unc_buses_int = zeros(size(unc_buses_ext));
for k = 1:numel(unc_buses_ext)
    bi = find(mpc_map.bus(:, BUS_I) == unc_buses_ext(k), 1);
    if isempty(bi)
        error('Uncertain bus ext #%d not found in case6ww.', unc_buses_ext(k));
    end
    unc_buses_int(k) = bi;
end

Delta_pu = Delta_MW(:) / baseMVA;

% Worst-case deviation margin per line: worst = sum_j |PTDF(l, b_j)| * Delta_j
PTDF_U = PTDF(:, unc_buses_int);   % nl x m
worst  = abs(PTDF_U) * Delta_pu;   % nl x 1 (p.u.)

Fmax = branch(:, RATE_A) / baseMVA; % p.u.

% Build OM and add robust linear constraints on Pg
om = opf_setup(mpc_i, mpopt);
idx = om.var.idx;
i1  = idx.i1.Pg;
iN  = idx.iN.Pg;
nv  = om.var.N;

if (iN - i1 + 1) ~= ng
    error('Pg dimension mismatch: OM has %d Pg vars, case has %d gens.', (iN-i1+1), ng);
end

Arows = [];
lvec  = [];
uvec  = [];

for ell = 1:nl
    if branch(ell, BR_STATUS) == 0
        continue;
    end
    if Fmax(ell) <= 0
        continue;
    end

    margin = Fmax(ell) - worst(ell);  % robust available margin

    % Nominal flow: mu_f = PTDF(ell,:)*(Cg*Pg - Pd)
    a_pg  = PTDF(ell,:) * Cg;         % 1 x ng
    cst   = PTDF(ell,:) * (-Pd);      % scalar

    % Enforce:  mu_f <= margin  => a_pg*Pg + cst <= margin => a_pg*Pg <= margin - cst
    %          -mu_f <= margin  => -a_pg*Pg - cst <= margin => -a_pg*Pg <= margin + cst
    rhs_pos = margin - cst;
    rhs_neg = margin + cst;

    Arows(end+1, :) =  a_pg; %#ok<SAGROW>
    lvec(end+1, 1)  = -Inf;
    uvec(end+1, 1)  = rhs_pos;

    Arows(end+1, :) = -a_pg; %#ok<SAGROW>
    lvec(end+1, 1)  = -Inf;
    uvec(end+1, 1)  = rhs_neg;
end

if ~isempty(Arows)
    A = sparse(Arows);
    Afull = sparse(size(A, 1), nv);
    Afull(:, i1:iN) = A;
    om = om.add_lin_constraint('ROBUST_LINE_LIMITS_BOX', Afull, lvec, uvec);
end

%% ===================== Solve =====================
try
    [res_i, success] = opf_execute(om, mpopt);
catch
    [res_i, success] = opf_execute(om, mpc_i, mpopt);
end

if ~success
    error('Robust DCOPF failed (infeasible or solver failure).');
end

results = int2ext(res_i, mpc);

%% ===================== Post-check robust line limit residual =====================
% Recompute nominal mu_f and verify: abs(mu_f) + worst <= Fmax
Pg_pu = res_i.gen(:, PG) / baseMVA;
mu_f  = PTDF * (Cg * Pg_pu - Pd);  % p.u.
lhs   = abs(mu_f) + worst;
viol  = max(lhs - Fmax, 0);

fprintf('\n=== Level-3 Robust DCOPF Summary (case6ww) ===\n');
fprintf('Uncertain buses (ext): %s\n', mat2str(unc_buses_ext(:)'));
fprintf('Delta (MW):            %s\n', mat2str(Delta_MW(:)'));
fprintf('Objective (total cost): %.6f\n', results.f);
fprintf('Max robust line viol:   %.6g p.u. (%.6g MW)\n', max(viol), max(viol) * baseMVA);

% Optional: print generator dispatch
fprintf('\nGenerator dispatch (MW):\n');
disp(results.gen(:, [GEN_BUS PG PMIN PMAX]));

