% We enforce: -Fmax+worst <= f_nom <= Fmax-worst, where f_nom = PTDF * (Pnet)
% Under DCOPF in MOST, the per-period variables include Pg and bus injections.
% We implement constraints in terms of Pg only: f = (PTDF*Cg)*Pg + const(Pd).
% This requires period-dependent Pd from profiles; we build constraints per period using expected Pd.

% Build generator-bus incidence Cg in internal indexing
ng_i = size(mpc_i.gen, 1);
Cg = sparse(mpc_i.gen(:, GEN_BUS), (1:ng_i)', 1, nb_i, ng_i);

% Extract base Pd (will be modified by profiles in MOST); we will create constraints using
% the period-specific Pd from mdi.mpc for each period after profile application.

if ~isfield(mdi, 'lin') || isempty(mdi.lin)
    mdi.lin = [];
end

for tt = 1:nt
    % Get period-tt mpc after profiles
    mpct = mdi.mpc(tt);
    mpct_i = ext2int(mpct);
    Pd_t = mpct_i.bus(:, PD) / baseMVA;  % p.u.

    % f = PTDF*(Cg*Pg - Pd)
    A_pg = PTDF * Cg;          % nl x ng
    cst  = PTDF * (-Pd_t);     % nl x 1

    % Only enforce for in-service branches with positive limits
    in_service = (branch_i(:, BR_STATUS) ~= 0) & (Fmax > 0);
    rows = find(in_service);

    A = A_pg(rows, :);
    c = cst(rows);
    margin = (Fmax(rows) - worst(rows));

    % Upper: A*Pg + c <= margin  => A*Pg <= margin - c
    % Lower: -(A*Pg + c) <= margin => -A*Pg <= margin + c
    Au = [ A; -A ];
    bu = [ margin - c; margin + c ];

    k = numel(mdi.lin) + 1;
    mdi.lin(k).name = sprintf('ROBUST_LINE_LIMITS_BOX_t%03d', tt);
    mdi.lin(k).A = sparse(Au);
    mdi.lin(k).l = -Inf(size(bu));
    mdi.lin(k).u = bu;
    mdi.lin(k).var = struct('t', tt, 'name', 'Pg');
end

%% 10) Solve MOST SCUC
mdo = most(mdi, mpopt);

if verbose
    ms = most_summary(mdo); %#ok<NASGU>
end

%% 11) Basic outputs
fprintf('\nMOST success: %d\n', mdo.QP.success);
if isfield(mdo, 'results')
    fprintf('Objective value (MOST): %.6f\n', mdo.results.f);
end

define_constants;

%% ==================== User Parameters ====================
useropt = struct();
useropt.casename   = 'case33mg';
useropt.model      = 'DC';
useropt.solver     = 'OT';          % MI(OPF) interface used by template
useropt.M          = 1e5;           % big-M
useropt.GUB        = 4;             % max number of opened branches
useropt.heuristic  = 'basic';
useropt.MaxTime    = 600;
useropt.MaxNodes   = 5e5;

% Emission objective settings
eta_emission = 100;

% If case has ng generators, build default coefficients (can be customized)
% alpha: constant, beta: linear, gamma: quadratic
% Here we create reasonable defaults and truncate/extend to ng.

t_start = tic;

%% ==================== Load Case and Apply Base Modifications ====================
mpc0 = loadcase(useropt.casename);

% --- Parameter modifications from base specification ---
% Bus 20, BS = 0.2
mpc0.bus(20, BS) = 0.2;
% Bus 17, VMIN = 1
mpc0.bus(17, VMIN) = 1.0;

% Branch (1->14), BR_X: scale to 1.2
k = find(mpc0.branch(:, F_BUS) == 1 & mpc0.branch(:, T_BUS) == 14);
if isempty(k)
    error('Branch (1->14) not found in case.');
end
mpc0.branch(k, BR_X) = 1.2 * mpc0.branch(k, BR_X);

% Branch (2->18), BR_R: scale to 1.1
k = find(mpc0.branch(:, F_BUS) == 2 & mpc0.branch(:, T_BUS) == 18);
if isempty(k)
    error('Branch (2->18) not found in case.');
end
mpc0.branch(k, BR_R) = 1.1 * mpc0.branch(k, BR_R);

%% ==================== Options ====================
mpopt = mpoption('model', useropt.model, 'verbose', 2, 'out.all', 0);
mpopt = mpoption(mpopt, 'opf.dc.solver', useropt.solver);
mpopt = mpoption(mpopt, 'opf.violation', 1e-8);

%% ==================== Build Internal Model ====================
mpc = ext2int(mpc0, mpopt);
om  = opf_setup(mpc, mpopt);

[baseMVA, bus, gen, branch] = deal(mpc.baseMVA, mpc.bus, mpc.gen, mpc.branch);
[nb, ng, nl] = deal(size(bus,1), size(gen,1), size(branch,1));

%% ==================== OTS Structural Changes ====================
% Remove tight bounds on original Pmis constraint to allow custom balance with Pf
if om.getN('lin', 'Pmis') > 0
    om.set_params('lin', 'Pmis', {'l', 'u'}, {-Inf(om.getN('lin','Pmis'),1), Inf(om.getN('lin','Pmis'),1)});
end

% Add explicit branch flow variable Pf and binary status Z
om.add_var('Pf', nl, zeros(nl,1));
om.add_var('Z',  nl, ones(nl,1),  [], [], 'B');

% Build DC matrices
[Bbus, Bf, Pbusinj, Pfinj] = makeBdc(baseMVA, bus, branch);

fbus = branch(:, F_BUS);
tbus = branch(:, T_BUS);
Cft  = sparse([(1:nl)'; (1:nl)'], [fbus; tbus], [ones(nl,1); -ones(nl,1)], nl, nb);
neg_Cg = sparse(gen(:, GEN_BUS), 1:ng, -1, nb, ng);

% Power balance with Pf and Pg: Cft'*Pf - Cg*Pg = -(Pd+Gs)/baseMVA - Pbusinj
A_pmis = [Cft'  neg_Cg];
b_pmis = -(bus(:, PD) + bus(:, GS)) / baseMVA - Pbusinj;

% Branch limits dependent on Z
Il = speye(nl);

il = find(branch(:, RATE_A) ~= 0 & branch(:, RATE_A) < 1e10);
Pmax = inf(nl,1);
Pmin = inf(nl,1);
if ~isempty(il)
    Pmax(il) = branch(il, RATE_A) / baseMVA - Pfinj(il);
    Pmin(il) = branch(il, RATE_A) / baseMVA + Pfinj(il);
end

% Big-M constraints tying Pf to Va when Z=1 (closed)
% Bf*Va - Pf = 0 if Z=1, relaxed if Z=0
rhsM = useropt.M * ones(nl,1);

% Add OTS constraints
om.add_lin_constraint('Pfl',   [Il,  diag(Pmin)], zeros(nl,1), [], {'Pf', 'Z'});
om.add_lin_constraint('Pfu',   [Il, -diag(Pmax)], [], zeros(nl,1), {'Pf', 'Z'});
om.add_lin_constraint('Pfmis', A_pmis, b_pmis, b_pmis, {'Pf', 'Pg'});
om.add_lin_constraint('Ml',    [Bf, -Il, -useropt.M*Il], -rhsM, [], {'Va', 'Pf', 'Z'});
om.add_lin_constraint('Mu',    [Bf, -Il,  useropt.M*Il], [],  rhsM, {'Va', 'Pf', 'Z'});

% Global limit on number of opened lines: sum(Z) >= nl - GUB
om.add_lin_constraint('GUB', ones(1, nl), nl-useropt.GUB, [], {'Z'});

%% ==================== DC-SCOPF N-1 Constraints (LODF-based) ====================
% Compute PTDF/LODF
PTDF = makePTDF(baseMVA, bus, branch);
LODF = makeLODF(branch, PTDF);

in_service = (branch(:, BR_STATUS) == 1);
has_limit  = (branch(:, RATE_A) > 0 & branch(:, RATE_A) < 1e10);
cont_set   = find(in_service & has_limit);
nc = length(cont_set);

constrain_lines = find(in_service & has_limit);
nL = length(constrain_lines);

if nc > 0 && nL > 0
    nv = om.var.N;
    iVa1 = om.var.idx.i1.Va;
    iVaN = om.var.idx.iN.Va;

    rateA = branch(:, RATE_A) / baseMVA;  % per-unit on baseMVA consistent with Bf

    nRows = 2 * nL * nc;
    Asec = spalloc(nRows, nv, 2 * nL * nc * nb);
    lsec = -inf(nRows, 1);
    usec =  inf(nRows, 1);

    row = 0;
    for kk = 1:nc
        k = cont_set(kk);
        lodf_col = LODF(:, k);       % nl x 1
        Bf_row_k = Bf(k, :);         % 1 x nb
        Pk       = Pfinj(k);         % scalar

        % Post-contingency flow model: (Bf + lodf*Bf(k,:))*Va + (Pfinj + lodf*Pfinj(k))
        Bf_k = Bf + lodf_col * Bf_row_k;
        Pf_k = Pfinj + lodf_col * Pk;

        for ii = 1:nL
            ell = constrain_lines(ii);
            limit = rateA(ell);

            aVa = Bf_k(ell, :);
            cst = Pf_k(ell);

            % Upper: aVa*Va + cst <= limit
            row = row + 1;
            Asec(row, iVa1:iVaN) = aVa;
            usec(row) = limit - cst;

            % Lower: -(aVa*Va + cst) <= limit  -> -aVa*Va <= limit + cst
            row = row + 1;
            Asec(row, iVa1:iVaN) = -aVa;
            usec(row) = limit + cst;
        end
    end

    om.add_lin_constraint('N1_branch_limits', Asec, lsec, usec);
end

%% ==================== Add Environmental (Emission) Quadratic Cost ====================
% Build coefficients sized to ng
alpha_em = 10 * ones(ng,1);
beta_em  = 2.0 * ones(ng,1);
gamma_em = 0.05 * ones(ng,1);

idx_i1 = om.var.idx.i1;
idx_iN = om.var.idx.iN;

nv = om.var.N;
Q = sparse(nv, nv);
c = zeros(nv, 1);

for i = 1:ng
    pg_idx = idx_i1.Pg + i - 1;
    Q(pg_idx, pg_idx) = Q(pg_idx, pg_idx) + 2 * eta_emission * gamma_em(i);
    c(pg_idx)         = c(pg_idx)         +     eta_emission * beta_em(i);
end
k0 = eta_emission * sum(alpha_em);

om.add_quad_cost('emission_cost', Q, c, k0);

%% ==================== Solve ====================
opt = mpopt2qpopt(mpopt, om.problem_type());

% Pass MI options (works when underlying solver uses intlinprog-like options)
if isfield(opt, 'intlinprog_opt')
    opt.intlinprog_opt = struct('MaxTime', useropt.MaxTime, 'MaxNodes', useropt.MaxNodes, 'Heuristics', useropt.heuristic);
else
    % keep silent if not supported by chosen solver
end

[x, f, eflag, output, lambda] = om.solve(opt);

if eflag <= 0
    error('OPF/OTS/SCOPF solve failed. eflag = %d', eflag);
end

%% ==================== Results Packaging ====================
results_int = mpc;
results_int.f = f;
results_int.success = (eflag > 0);
results_int.eflag = eflag;
results_int.output = output;
results_int.lambda = lambda;

% Map key variables back into MATPOWER matrices
Va = x(idx_i1.Va:idx_iN.Va);
Pg = x(idx_i1.Pg:idx_iN.Pg);

results_int.bus(:, VA) = Va * 180/pi;
results_int.gen(:, PG) = Pg;

% Optional: store OTS variables
iPf1 = om.var.idx.i1.Pf; iPfN = om.var.idx.iN.Pf;
iZ1  = om.var.idx.i1.Z;  iZN  = om.var.idx.iN.Z;
results_int.branch(:, PF) = x(iPf1:iPfN) * baseMVA;   % MW
results_int.ots.Z = x(iZ1:iZN);

results = int2ext(results_int);

fprintf('Solved in %.2f seconds\n', toc(t_start));
fprintf('Objective value (incl. emission): %.6f\n', f);

disp('Selected opened lines (Z ~ 0):');
opened = find(results_int.ots.Z < 0.5);
disp(opened);

clear; clc;
define_constants;

%% ========================= Load base case =========================
mpc = loadcase('case22');

%% ========================= Solver / options =========================
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'AC');
mpopt = mpoption(mpopt, 'opf.ac.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);

%% ========================= Parameter modifications =========================
% 1) Bus 8, QD: scale to 0
mpc.bus(8, QD) = 0;

% 2) Generator at bus 1, QMIN: set to -50
g1 = find(mpc.gen(:, GEN_BUS) == 1, 1, 'first');
if isempty(g1)
    error('No generator found at bus 1.');
end
mpc.gen(g1, QMIN) = -50;

% 3) Branch (11->19), BR_R: scale to 2
k = find(mpc.branch(:, F_BUS) == 11 & mpc.branch(:, T_BUS) == 19, 1, 'first');
if isempty(k)
    error('Branch 11->19 not found in case22.');
end
mpc.branch(k, BR_R) = 2 * mpc.branch(k, BR_R);

% 4) Branch (22->1), BR_B: scale to 1.1
k = find(mpc.branch(:, F_BUS) == 22 & mpc.branch(:, T_BUS) == 1, 1, 'first');
if isempty(k)
    error('Branch 22->1 not found in case22.');
end
mpc.branch(k, BR_B) = 1.1 * mpc.branch(k, BR_B);

%% ========================= Structural modification 1: Load shedding =========================
nb  = size(mpc.bus, 1);
ng0 = size(mpc.gen, 1);

load_buses = find(mpc.bus(:, PD) > 0);
nl = length(load_buses);

ncol_gen = size(mpc.gen, 2);
new_gen = zeros(nl, ncol_gen);

for kk = 1:nl
    b = load_buses(kk);
    Pd_k = mpc.bus(b, PD);

    % template from first generator row (keeps consistent width)
    g = mpc.gen(1, :);

    % virtual shedding generator
    g(GEN_BUS)    = b;
    g(PG)         = 0;
    g(QG)         = 0;
    g(QMAX)       = 0;
    g(QMIN)       = 0;
    g(VG)         = 1.0;
    g(GEN_STATUS) = 1;
    g(PMAX)       = Pd_k;   % maximum shed = original load
    g(PMIN)       = 0;

    new_gen(kk, :) = g;
end

mpc.gen = [mpc.gen; new_gen];
ng = size(mpc.gen, 1);
shed_gen_idx = (ng0+1:ng)';

% gencost for shedding units
ncol_gc = size(mpc.gencost, 2);
if ncol_gc < 7
    error('Unexpected gencost format: expected polynomial cost with at least 7 columns.');
end

old_cost = mpc.gencost;

% Shedding penalty (high)
p_cost = 100  * ones(nl, 1);
q_cost = 1000 * ones(nl, 1);
r_cost = 5000 * ones(nl, 1);

new_cost = zeros(nl, ncol_gc);
new_cost(:, 1) = 2;   % polynomial
new_cost(:, 2) = 0;   % startup
new_cost(:, 3) = 0;   % shutdown
new_cost(:, 4) = 3;   % quadratic
new_cost(:, 5) = r_cost;
new_cost(:, 6) = q_cost;
new_cost(:, 7) = p_cost;

mpc.gencost = [old_cost; new_cost];

%% ========================= Build OPF model =========================
om = opf_setup(mpc, mpopt);
idx_i1 = om.var.idx.i1;
idx_iN = om.var.idx.iN;
baseMVA = mpc.baseMVA;

%% ========================= Structural modification 2: Reactive power quadratic cost =========================
% user-defined per-generator coefficients (length = ng)
% Here: assign higher cost to the first few generators; low cost for the rest;
% shedding units have Qg fixed at 0, so their Q cost has no effect.
c_Q = 10 * ones(ng, 1);
if ng >= 1, c_Q(1) = 100; end
if ng >= 2, c_Q(2) = 10;  end
if ng >= 3, c_Q(3) = 100; end

Q_mat = sparse(1:ng, 1:ng, 2*c_Q, ng, ng);
om = om.add_quad_cost('reactive_support_cost', Q_mat, [], 0, {'Qg'});

%% ========================= Structural modification 3: Regulation-up reserve =========================
% Reserve parameters
RUmax_MW = 50 * ones(ng, 1);

% Regions are defined over generator indices.
% Template requested regions { [1 2], [3] }, but to be robust for case22 with >3 gens:
% use region1 = [1 2], region2 = [3..ng] (if ng<3, region2 may be empty).
regions = {};
if ng >= 2
    regions{1} = [1 2];
else
    regions{1} = 1:ng;
end
if ng >= 3
    regions{2} = 3:ng;
else
    regions{2} = []; %#ok<AGROW>
end

% Region requirements (MW)
R_RU_MW = 50 * ones(numel(regions), 1);

RUmax_pu = RUmax_MW / baseMVA;
R_RU_pu  = R_RU_MW  / baseMVA;

% Add RU decision variables
om.add_var('RU', ng, zeros(ng,1), zeros(ng,1), RUmax_pu);

% Build indices
iPg = idx_i1.Pg : idx_iN.Pg;
iRU = om.var.idx.i1.RU : om.var.idx.iN.RU;
nv  = om.var.N;

% (1) Pg + RU <= Pmax (all in p.u.)
A = sparse(ng, nv);
A(:, iPg) = speye(ng);
A(:, iRU) = speye(ng);
u_pu = mpc.gen(:, PMAX) / baseMVA;
om.add_lin_constraint('Pg_plus_RU_le_Pmax', A, -inf(ng,1), u_pu);

% (2) Regional sum(RU) >= requirement
nr = numel(regions);
Areg = sparse(nr, nv);
for r = 1:nr
    if ~isempty(regions{r})
        Areg(r, iRU(regions{r})) = 1;
    end
end
om.add_lin_constraint('region_RU_requirement', Areg, R_RU_pu, inf(nr,1));

%% ========================= Solve =========================
[x, f, eflag, output, lambda] = om.solve();
if eflag <= 0
    error('AC-OPF (with load shedding + Q cost + RU constraints) did not converge, eflag=%d', eflag);
end

%% ========================= Recover solution into results struct =========================
results = mpc;
results.success = 1;
results.f = f;

Vm_solution = x(idx_i1.Vm:idx_iN.Vm);
Va_solution = x(idx_i1.Va:idx_iN.Va);
Pg_solution = x(idx_i1.Pg:idx_iN.Pg);
Qg_solution = x(idx_i1.Qg:idx_iN.Qg);
RU_solution = x(iRU);

results.bus(:, VM) = Vm_solution;
results.bus(:, VA) = Va_solution * 180/pi;
results.gen(:, PG) = Pg_solution;
results.gen(:, QG) = Qg_solution;

%% ========================= Reporting =========================
fprintf('\n=== AC-OPF Level-3: Load Shedding + Reactive Q Cost + Regulation-Up ===\n');
fprintf('Total objective = %.6f\n', results.f);

% Load shedding summary
Pg_all = results.gen(:, PG);
Lshd   = Pg_all(shed_gen_idx);
orig_load = mpc.bus(load_buses, PD);
remain_load = orig_load - Lshd;

total_orig   = sum(orig_load);
total_shed   = sum(Lshd);
total_remain = total_orig - total_shed;

% Shedding cost (matches polynomial coefficients)
shed_cost = sum(p_cost + q_cost .* Lshd + r_cost .* (Lshd.^2));

fprintf('\n-- Load Shedding Summary --\n');
fprintf('  Total original load   = %10.3f MW\n', total_orig);
fprintf('  Total shed load       = %10.3f MW\n', total_shed);
fprintf('  Total remaining load  = %10.3f MW\n', total_remain);
if total_orig > 0
    fprintf('  Overall shed ratio    = %10.3f %%\n', 100 * total_shed / total_orig);
end
fprintf('  Load shedding cost    = %10.3f\n', shed_cost);

fprintf('\nBus  OrigLoad    ShedLoad   RemainLoad  ShedRatio(%%)\n');
for kk = 1:nl
    b = load_buses(kk);
    ratio = 0;
    if orig_load(kk) > 0
        ratio = 100 * Lshd(kk) / orig_load(kk);
    end
    fprintf('%3d  %10.3f  %10.3f  %10.3f  %10.3f\n', b, orig_load(kk), Lshd(kk), remain_load(kk), ratio);
end

% RU summary
RU_MW = RU_solution * baseMVA;
fprintf('\n-- Regulation Up (RU) Summary --\n');
fprintf('  Total RU procured = %10.3f MW\n', sum(RU_MW));
for r = 1:nr
    if isempty(regions{r})
        proc = 0;
    else
        proc = sum(RU_MW(regions{r}));
    end
    fprintf('  Region %d: RU procured = %10.3f MW, requirement = %10.3f MW\n', r, proc, R_RU_MW(r));
end

