mpc = loadcase(useropt.casename);

% ---- Gen cost modifications for generator at bus 8 ----
% Find generator row(s) at GEN_BUS == 8
ig8 = find(mpc.gen(:, GEN_BUS) == 8);
if isempty(ig8)
    error('No generator found at bus 8 in %s.', useropt.casename);
end

% MATPOWER gencost (polynomial): [MODEL STARTUP SHUTDOWN NCOST c(n-1) ... c0]
% COST_PARAMS_C3 corresponds to the cubic coefficient when NCOST >= 4.
% COST_PARAMS_C1 corresponds to the linear coefficient.
for k = 1:numel(ig8)
    r = ig8(k);
    if mpc.gencost(r, MODEL) ~= POLYNOMIAL
        error('Generator cost model at bus 8 is not polynomial; cannot scale C3/C1 safely.');
    end
    ncost = mpc.gencost(r, NCOST);
    if ncost < 2
        error('Polynomial cost at bus 8 has NCOST < 2; cannot scale linear coefficient.');
    end

    % coefficient positions in gencost row
    % coefficients occupy the last ncost entries: c(ncost-1) ... c0
    cidx_start = size(mpc.gencost,2) - ncost + 1;
    coeffs = mpc.gencost(r, cidx_start:end);

    % Scale C3 (cubic) by 1.0 if present (ncost>=4)
    if ncost >= 4
        % cubic is the first coefficient when order is 3 (ncost=4): [c3 c2 c1 c0]
        coeffs(1) = coeffs(1) * 1.0;
    end

    % Scale C1 (linear) by 1.1 (present when ncost>=2)
    if ncost == 2
        % [c1 c0]
        coeffs(1) = coeffs(1) * 1.1;
    elseif ncost == 3
        % [c2 c1 c0]
        coeffs(2) = coeffs(2) * 1.1;
    else
        % ncost >= 4 : [c3 c2 c1 c0 ...]
        coeffs(3) = coeffs(3) * 1.1;
    end

    mpc.gencost(r, cidx_start:end) = coeffs;
end

% ---- Branch (5 -> 14) BR_STATUS set to 1 ----
ibr_514 = find(mpc.branch(:, F_BUS) == 5 & mpc.branch(:, T_BUS) == 14);
if isempty(ibr_514)
    % also try reversed direction in case data is stored oppositely
    ibr_514 = find(mpc.branch(:, F_BUS) == 14 & mpc.branch(:, T_BUS) == 5);
end
if isempty(ibr_514)
    error('Branch (5,14) not found in %s.', useropt.casename);
end
mpc.branch(ibr_514, BR_STATUS) = 1;

% ---- Branch (43 -> 5) BR_X scale by 1.2 ----
ibr_435 = find(mpc.branch(:, F_BUS) == 43 & mpc.branch(:, T_BUS) == 5);
if isempty(ibr_435)
    ibr_435 = find(mpc.branch(:, F_BUS) == 5 & mpc.branch(:, T_BUS) == 43);
end
if isempty(ibr_435)
    error('Branch (43,5) not found in %s.', useropt.casename);
end
mpc.branch(ibr_435, BR_X) = mpc.branch(ibr_435, BR_X) * 1.2;

%% ================= Solver / OPF options =================
mpopt = mpoption('model', useropt.model, 'verbose', 2, 'out.all', 0);
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);
mpopt = mpoption(mpopt, 'opf.dc.solver', useropt.solver);

%% ================= Internal indexing and OM setup =================
mpc_i = ext2int(mpc, mpopt);
om = opf_setup(mpc_i, mpopt);

[baseMVA, bus, gen, branch] = deal(mpc_i.baseMVA, mpc_i.bus, mpc_i.gen, mpc_i.branch);
[nb, ng, nl] = deal(size(bus,1), size(gen,1), size(branch,1));

%% ================= OTS structural modification (based on template 2_OTS) =================
% Relax/remove original Pmis bounds (turn equality into free, then re-impose with our constraints)
om.set_params('lin', 'Pmis', {'l', 'u'}, {-Inf(om.getN('lin','Pmis'),1), Inf(om.getN('lin','Pmis'),1)});

% Add branch flow variables Pf and binary line status Z
om.add_var('Pf', nl, zeros(nl,1));
om.add_var('Z',  nl, ones(nl,1), [], [], 'B');

% Build DC matrices
[Bbus, Bf, Pbusinj, Pfinj] = makeBdc(baseMVA, bus, branch);

f = branch(:, F_BUS);
t = branch(:, T_BUS);
Cft = sparse([(1:nl)'; (1:nl)'], [f; t], [ones(nl,1); -ones(nl,1)], nl, nb);
neg_Cg = sparse(gen(:, GEN_BUS), (1:ng)', -1, nb, ng);
Aeq = [Cft' neg_Cg];
beq = -(bus(:, PD) + bus(:, GS)) / baseMVA - Pbusinj;

Il  = speye(nl);
rhs = useropt.M * ones(nl, 1);

% Branch flow limits (only where RATE_A is meaningful)
il = find(branch(:, RATE_A) ~= 0 & branch(:, RATE_A) < 1e10);
Pmax = inf(nl,1);
Pmin = inf(nl,1);
if ~isempty(il)
    Pmax(il) = branch(il, RATE_A) / baseMVA - Pfinj(il);
    Pmin(il) = branch(il, RATE_A) / baseMVA + Pfinj(il);
end

% Add linear constraints for flow limits with switching variable Z
% Pf - Pmin.*Z >= 0  (when Z=0, forces Pf >= 0; matches given template)
% Pf + Pmax.*Z <= 0  (when Z=0, forces Pf <= 0)
% NOTE: This mirrors the provided template exactly.
om.add_lin_constraint('Pfl', [Il,  diag(Pmin)], zeros(nl,1), [], {'Pf','Z'});
om.add_lin_constraint('Pfu', [Il, -diag(Pmax)], [], zeros(nl,1), {'Pf','Z'});

% Power balance: Cft' * Pf - Cg*Pg = b
om.add_lin_constraint('Pfmis', Aeq, beq, beq, {'Pf','Pg'});

% Big-M linking: when Z=1, Pf = Bf*Va; when Z=0, relaxed by M
om.add_lin_constraint('Ml', [Bf, -Il, -useropt.M*Il], -rhs, [], {'Va','Pf','Z'});
om.add_lin_constraint('Mu', [Bf, -Il,  useropt.M*Il], [],  rhs, {'Va','Pf','Z'});

% Global switching budget: at most GUB lines can be opened
% Z=1 means closed; sum(Z) >= nl - GUB
om.add_lin_constraint('GUB', ones(1,nl), nl-useropt.GUB, [], {'Z'});

%% ================= Robust DC line limit tightening (based on template 4_robust_OPF) =================
% Ensure RATE_A is not all-zero (avoid meaningless constraints)
rateA = branch(:, RATE_A);
if all(rateA == 0)
    branch(:, RATE_A) = 250;  % fallback
else
    branch(rateA == 0, RATE_A) = 1e4;
end
mpc_i.branch = branch;  % keep in mpc_i too

% PTDF for internal system
PTDF = makePTDF(baseMVA, bus, branch);  % nl x nb

Cg = sparse(gen(:, GEN_BUS), (1:ng)', 1, nb, ng);
Pd = bus(:, PD) / baseMVA;

% Map uncertain buses ext -> int using the same ext2int mapping
% Use the pre-ext2int case as reference mapping
mpc0 = loadcase(useropt.casename);
% apply same topology/cost parameter edits to mpc0 for consistent mapping, but only need bus mapping
% (bus numbering mapping is unchanged by our edits; ext2int mapping depends on bus status/ordering)
mpc0_i = ext2int(mpc0);
unc_buses_int = zeros(size(unc_buses_ext));
for k = 1:numel(unc_buses_ext)
    bi = find(mpc0_i.bus(:, BUS_I) == unc_buses_ext(k), 1);
    if isempty(bi)
        error('Uncertain bus ext #%d not found after ext2int mapping.', unc_buses_ext(k));
    end
    unc_buses_int(k) = bi;
end

Delta_pu = Delta_MW(:) / baseMVA;
PTDF_U = PTDF(:, unc_buses_int);
worst  = abs(PTDF_U) * Delta_pu;     % nl x 1

Fmax = branch(:, RATE_A) / baseMVA;

% Add robust constraints as linear inequalities in Pg only
idx = om.var.idx;
i1 = idx.i1.Pg;
iN = idx.iN.Pg;
nv = om.var.N;
if (iN - i1 + 1) ~= ng
    error('Pg dimension mismatch in OM.');
end

Arows = [];
lvec  = [];
uvec  = [];

for ell = 1:nl
    if branch(ell, BR_STATUS) == 0
        continue;
    end
    if Fmax(ell) <= 0
        continue;
    end

    margin = Fmax(ell) - worst(ell);
    a_pg   = PTDF(ell,:) * Cg;         % 1 x ng
    const  = PTDF(ell,:) * (-Pd);      % scalar

    rhs_pos = margin - const;
    rhs_neg = margin + const;

    % mu_f <= margin
    Arows(end+1, :) =  a_pg; %#ok<AGROW>
    lvec(end+1, 1)  = -Inf;  %#ok<AGROW>
    uvec(end+1, 1)  =  rhs_pos; %#ok<AGROW>

    % -mu_f <= margin
    Arows(end+1, :) = -a_pg; %#ok<AGROW>
    lvec(end+1, 1)  = -Inf;  %#ok<AGROW>
    uvec(end+1, 1)  =  rhs_neg; %#ok<AGROW>
end

if ~isempty(Arows)
    A = sparse(Arows);
    Afull = sparse(size(A,1), nv);
    Afull(:, i1:iN) = A;
    om.add_lin_constraint('ROBUST_LINE_LIMITS_BOX', Afull, lvec, uvec);
end

%% ================= Solve (MILP) =================
opt = mpopt2qpopt(mpopt, om.problem_type());
opt.intlinprog_opt = struct('MaxTime', useropt.MaxTime, 'MaxNodes', useropt.MaxNodes, 'Heuristics', useropt.heuristic);

[res_i, F, eflag, output, lambda] = om.solve(opt);

% Convert results back to external indexing
results = int2ext(res_i, mpc);

% Optional post-check of robust constraint: |mu_f| + worst <= Fmax
mpc_chk = ext2int(mpc);
baseMVA_chk = mpc_chk.baseMVA;
PTDF_chk = makePTDF(baseMVA_chk, mpc_chk.bus, mpc_chk.branch);
Cg_chk = sparse(mpc_chk.gen(:, GEN_BUS), (1:size(mpc_chk.gen,1))', 1, size(mpc_chk.bus,1), size(mpc_chk.gen,1));
Pd_chk = mpc_chk.bus(:, PD) / baseMVA_chk;

% Recompute mapping for uncertain buses on chk system
unc_buses_int_chk = zeros(size(unc_buses_ext));
for k = 1:numel(unc_buses_ext)
    bi = find(mpc_chk.bus(:, BUS_I) == unc_buses_ext(k), 1);
    if isempty(bi)
        error('Uncertain bus ext #%d not found in check mapping.', unc_buses_ext(k));
    end
    unc_buses_int_chk(k) = bi;
end

worst_chk = abs(PTDF_chk(:, unc_buses_int_chk)) * (Delta_MW(:)/baseMVA_chk);
Fmax_chk  = mpc_chk.branch(:, RATE_A) / baseMVA_chk;

Pg_pu = res_i.gen(:, PG) / baseMVA_chk;
mu_f  = PTDF_chk * (Cg_chk*Pg_pu - Pd_chk);
viol  = max(abs(mu_f) + worst_chk - Fmax_chk, 0);

fprintf('\n=== DC OTS + Robust (box) summary ===\n');
fprintf('Success flag (eflag): %d\n', eflag);
fprintf('Objective: %.6f\n', results.f);
fprintf('unc buses (ext): %s\n', mat2str(unc_buses_ext(:)'));
fprintf('Delta (MW):      %s\n', mat2str(Delta_MW(:)'));
fprintf('Max robust viol: %.6g p.u. (%.6g MW)\n', max(viol), max(viol)*baseMVA_chk);

%% Level 3: DC-OTS + DC-SCOPF (N-1) for case118zh with cost modification
clear; clc;

%% ---------------- User options ----------------
useropt = struct();
useropt.casename   = 'case118zh';
useropt.model      = 'DC';
useropt.solver     = 'OT';          % integer-capable DC OPF solver hook (per template)
useropt.M          = 1e5;           % Big-M
useropt.GUB        = 4;             % global upper bound on number of opened lines (sum(Z) >= nl-GUB)
useropt.heuristic  = 'basic';
useropt.MaxTime    = 600;
useropt.MaxNodes   = 5e5;
useropt.verbose    = 2;
useropt.out_all    = 0;
useropt.opf_violation = 1e-8;

t_start = tic;

%% ---------------- Init ----------------
define_constants;
mpc0 = loadcase(useropt.casename);
if isempty(mpc0)
    error('Failed to load case: %s', useropt.casename);
end

%% ---------------- Parameter modification: scale COST_PARAMS_C3 of gen at bus 8 ----------------
% MATPOWER gencost format (POLYNOMIAL): [MODEL STARTUP SHUTDOWN NCOST c(n-1) ... c0]
% For cubic polynomial NCOST=4 => [c3 c2 c1 c0] are in columns 5..8.
% We scale c3 for generators whose GEN_BUS == 8.
mpc = mpc0;
if isfield(mpc, 'gencost') && ~isempty(mpc.gencost)
    is_poly = (mpc.gencost(:, MODEL) == POLYNOMIAL);
    is_bus8 = (mpc.gen(:, GEN_BUS) == 8);
    idx = find(is_poly & is_bus8);
    for k = 1:length(idx)
        r = idx(k);
        ncost = mpc.gencost(r, NCOST);
        if ncost >= 4
            c3_col = 5; % first polynomial coefficient column
            mpc.gencost(r, c3_col) = 1.1 * mpc.gencost(r, c3_col);
        else
            warning('Generator at bus 8 has NCOST=%d < 4, no cubic term to scale.', ncost);
        end
    end
else
    warning('No gencost data found; cost modification skipped.');
end

%% ---------------- MPOptions ----------------
mpopt = mpoption('model', useropt.model, ...
    'verbose', useropt.verbose, 'out.all', useropt.out_all, ...
    'opf.dc.solver', useropt.solver, ...
    'opf.violation', useropt.opf_violation);

%% Convert to internal indexing and build OPF model
mpc = ext2int(mpc, mpopt);
om  = opf_setup(mpc, mpopt);

fprintf('\n%s DC-OTS + DC-SCOPF (N-1) %s\n', repmat('=', 1, 30), repmat('=', 1, 30));

%% ---------------- Extract data ----------------
[baseMVA, bus, gen, branch] = deal(mpc.baseMVA, mpc.bus, mpc.gen, mpc.branch);
[nb, ng, nl] = deal(size(bus,1), size(gen,1), size(branch,1));

%% ---------------- DC-OTS structural changes ----------------
% Relax original Pmis bounds (effectively remove standard nodal balance constraint bounds)
if om.getN('lin', 'Pmis') > 0
    om.set_params('lin', 'Pmis', {'l','u'}, {-Inf(om.getN('lin','Pmis'),1), Inf(om.getN('lin','Pmis'),1)});
end

% Add branch flow variables Pf and binary line-status variables Z
% Pf: real-valued branch flows (p.u.)
% Z: binary status-like variable (1 means closed, 0 means opened)
om.add_var('Pf', nl, zeros(nl,1));
om.add_var('Z',  nl, ones(nl,1), [], [], 'B');

% Build matrices for DC model
[B, Bf, Pbusinj, Pfinj] = makeBdc(baseMVA, bus, branch);

f = branch(:, F_BUS);
t = branch(:, T_BUS);
Cft = sparse([(1:nl)'; (1:nl)'], [f; t], [ones(nl,1); -ones(nl,1)], nl, nb);
neg_Cg = sparse(gen(:, GEN_BUS), 1:ng, -1, nb, ng);
Aeq = [Cft' neg_Cg];
beq = -(bus(:, PD) + bus(:, GS)) / baseMVA - Pbusinj;

Il  = speye(nl);
rhs = useropt.M * ones(nl, 1);

% Branch thermal limits (RATE_A) in p.u. with injection offsets
in_service = (branch(:, BR_STATUS) == 1);
has_limit  = (branch(:, RATE_A) > 0) & (branch(:, RATE_A) < 1e10);
il = find(in_service & has_limit);

Pmax = inf(nl,1);
Pmin = inf(nl,1);
if ~isempty(il)
    Pmax(il) = branch(il, RATE_A) / baseMVA - Pfinj(il);
    Pmin(il) = branch(il, RATE_A) / baseMVA + Pfinj(il);
end

% Add OTS constraints
% Flow limits with switching (two-sided implemented as two constraints)
om.add_lin_constraint('Pfl',  [Il,  diag(Pmin)],  zeros(nl,1), [],           {'Pf','Z'});
om.add_lin_constraint('Pfu',  [Il, -diag(Pmax)],  [],            zeros(nl,1), {'Pf','Z'});

% Nodal balance using Pf and Pg
om.add_lin_constraint('Pfmis', Aeq, beq, beq, {'Pf','Pg'});

% Big-M constraints linking Va, Pf, Z:
% Bf*Va - Pf <=  M*(1-Z)
% Bf*Va - Pf >= -M*(1-Z)
% Written as:
%   (Bf)Va + (-I)Pf + (-M I)Z <= -M
%   (Bf)Va + (-I)Pf + ( M I)Z <=  M
om.add_lin_constraint('Ml',  [Bf, -Il, -useropt.M*Il], -rhs, [], {'Va','Pf','Z'});
om.add_lin_constraint('Mu',  [Bf, -Il,  useropt.M*Il],  [], rhs, {'Va','Pf','Z'});

% Global upper bound on number of opened lines: sum(Z) >= nl - GUB
om.add_lin_constraint('GUB', ones(1,nl), nl - useropt.GUB, [], {'Z'});

%% ---------------- DC-SCOPF (N-1) constraints using LODF ----------------
% Compute PTDF/LODF from base (pre-switching) topology.
% Note: This enforces N-1 security on the base-topology DC network.
PTDF = makePTDF(baseMVA, bus, branch);
LODF = makeLODF(branch, PTDF);

rateA = branch(:, RATE_A) / baseMVA; % convert to p.u. for comparison with Bf*Va + Pfinj

% Contingency set: in-service lines with limits
cont_set = find(in_service & has_limit);
nc = length(cont_set);

% Monitored lines: in-service with limits
mon_set = find(in_service & has_limit);
nL = length(mon_set);

if nc > 0 && nL > 0
    nv = om.var.N;
    iVa1 = om.var.idx.i1.Va;
    iVaN = om.var.idx.iN.Va;

    nRows = 2 * nL * nc;
    Asec = spalloc(nRows, nv, nRows * min(nb, 50)); % conservative prealloc
    lsec = -inf(nRows, 1);
    usec =  inf(nRows, 1);

    row = 0;
    for kk = 1:nc
        k = cont_set(kk);
        lodf_col = LODF(:, k);     % nl x 1
        Bf_row_k = Bf(k, :);       % 1 x nb
        Pk       = Pfinj(k);       % scalar

        % Post-contingency mapping
        Bf_k = Bf + lodf_col * Bf_row_k;
        Pf_k = Pfinj + lodf_col * Pk;

        for ii = 1:nL
            ell = mon_set(ii);
            limit = rateA(ell);

            aVa = Bf_k(ell, :);
            cst = Pf_k(ell);

            % Upper: aVa*Va + cst <= limit  -> aVa*Va <= limit - cst
            row = row + 1;
            Asec(row, iVa1:iVaN) = aVa;
            usec(row) = limit - cst;

            % Lower: -(aVa*Va + cst) <= limit -> (-aVa)*Va <= limit + cst
            row = row + 1;
            Asec(row, iVa1:iVaN) = -aVa;
            usec(row) = limit + cst;
        end
    end

    if row ~= nRows
        error('N-1 constraint row count mismatch: row=%d, expected=%d', row, nRows);
    end

    om.add_lin_constraint('N1_branch_limits', Asec, lsec, usec);
else
    warning('No N-1 security constraints added (empty contingency or monitor set).');
end

%% ---------------- Solve ----------------
opt = mpopt2qpopt(mpopt, om.problem_type());
% intlinprog options used by OT-based MILP/MIP workflow (per template)
opt.intlinprog_opt = struct('MaxTime', useropt.MaxTime, ...
                            'MaxNodes', useropt.MaxNodes, ...
                            'Heuristics', useropt.heuristic);

[x, f, eflag, output, lambda] = om.solve(opt);

fprintf('Solved in %.2f seconds\n', toc(t_start));

if eflag <= 0
    error('Solver failed, eflag = %d', eflag);
end

%% ---------------- Build results ----------------
idx_i1 = om.var.idx.i1;
idx_iN = om.var.idx.iN;

Va = x(idx_i1.Va:idx_iN.Va);
Pg = x(idx_i1.Pg:idx_iN.Pg);
Pf = x(idx_i1.Pf:idx_iN.Pf);
Z  = x(idx_i1.Z :idx_iN.Z );

results = mpc;
results.bus(:, VA) = Va * 180/pi;
results.gen(:, PG) = Pg * baseMVA; % Pg in MW for reporting

% Store OTS outputs in a custom field
results.ots.Pf_pu = Pf;
results.ots.Z     = Z;
results.f         = f;
results.success   = (eflag > 0);
results.eflag     = eflag;
results.output    = output;
results.lambda    = lambda;

results = int2ext(results);

%% ---------------- Report ----------------
fprintf('\n=== DC-OTS + N-1 DC-SCOPF finished ===\n');
fprintf('Objective value: %.6f\n', f);
if isfield(output, 'alg')
    fprintf('Solver: %s\n', output.alg);
end
if isfield(output, 'iterations')
    fprintf('Iterations: %d\n', output.iterations);
end

fprintf('\nNumber of opened lines (approx): %g\n', sum(1 - results.ots.Z));

fprintf('\nGenerator dispatch (MW):\n');
disp(results.gen(:, PG));

fprintf('\nBus voltage angles (deg):\n');
disp(results.bus(:, VA));

define_constants;
clear; clc;

%% ===================== 1) Load base case & options =====================
mpc0 = loadcase('case5');

verbose = 1;
mpopt = mpoption('verbose', verbose, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'DC');
