mpopt = mpoption(mpopt, 'most.dc_model', 1);
mpopt = mpoption(mpopt, 'most.price_stage_warn_tol', 1e-5);

% base spec solving requirement
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);

% tighten MILP tolerances if available
if have_feature('intlinprog')
    mpopt = mpoption(mpopt, 'linprog.Algorithm', 'dual-simplex');
    mpopt = mpoption(mpopt, 'intlinprog.RootLPAlgorithm', 'dual-simplex');
    mpopt = mpoption(mpopt, 'intlinprog.TolCon', 1e-9);
    mpopt = mpoption(mpopt, 'intlinprog.TolGapAbs', 0);
    mpopt = mpoption(mpopt, 'intlinprog.TolGapRel', 0);
    mpopt = mpoption(mpopt, 'intlinprog.TolInteger', 1e-6);
end

%% ===================== 2) Apply parameter modifications =====================
mpc = mpc0;

% (a) Bus 3, VMAX -> scale to 1.04 (interpret as set to 1.04)
bus3 = find(mpc.bus(:, BUS_I) == 3, 1);
if isempty(bus3)
    error('Bus 3 not found in case5');
end
mpc.bus(bus3, VMAX) = 1.04;

% (b) Generator at bus 2, COST_PARAMS_C3 (quadratic coefficient c2) scale by 1.1
% MATPOWER polynomial cost: [MODEL STARTUP SHUTDOWN NCOST c2 c1 c0]
g2 = find(mpc.gen(:, GEN_BUS) == 2 & mpc.gen(:, GEN_STATUS) > 0, 1);
if isempty(g2)
