end
mpc.gencost(g2, 5) = 1.1 * mpc.gencost(g2, 5);   % scale c2

% (c) Branch (3 -> 4), BR_X scale by 1.1
br34 = find(mpc.branch(:, F_BUS) == 3 & mpc.branch(:, T_BUS) == 4, 1);
if isempty(br34)
    error('Branch 3->4 not found in case5');
end
mpc.branch(br34, BR_X) = 1.1 * mpc.branch(br34, BR_X);

%% ===================== 3) Add load shedding via virtual generators =====================
% Add one virtual generator at each bus with PD > 0
load_buses = find(mpc.bus(:, PD) > 0);
nlbus = length(load_buses);
ng0 = size(mpc.gen, 1);

ncol_gen = size(mpc.gen, 2);
new_gen = zeros(nlbus, ncol_gen);
for k = 1:nlbus
    b = load_buses(k);
    Pd_k = mpc.bus(b, PD);

    gtmp = mpc.gen(1, :);
