    gtmp(QMAX) = 0;
    gtmp(QMIN) = 0;
    gtmp(VG) = 1.0;
    gtmp(GEN_STATUS) = 1;
    gtmp(PMAX) = Pd_k;
    gtmp(PMIN) = 0;
    new_gen(k, :) = gtmp;
end
mpc.gen = [mpc.gen; new_gen];
shed_gen_idx = (ng0+1:size(mpc.gen,1))';

% Add high penalty costs for shedding generators
ncol_gc = size(mpc.gencost, 2);
if ncol_gc < 7
    % create a standard polynomial gencost matrix if needed
    old = mpc.gencost;
    mpc.gencost = zeros(size(old,1), 7);
    mpc.gencost(:,1:min(end,size(old,2))) = old(:,1:min(end,size(old,2)));
    ncol_gc = 7;
end

old_cost = mpc.gencost;
new_cost = zeros(nlbus, ncol_gc);
new_cost(:, MODEL) = 2;
new_cost(:, STARTUP) = 0;
new_cost(:, SHUTDOWN) = 0;
new_cost(:, NCOST) = 3;

% penalty coefficients
p_cost = 100  * ones(nlbus, 1);
q_cost = 1000 * ones(nlbus, 1);
r_cost = 5000 * ones(nlbus, 1);

new_cost(:, 5) = r_cost; % c2
new_cost(:, 6) = q_cost; % c1
new_cost(:, 7) = p_cost; % c0

mpc.gencost = [old_cost; new_cost];

%% ===================== 4) Build/attach MOST UC data (xgd) =====================
% Use an example xgd_uc file as a generic UC data source.
% (If not available in your installation, replace with your own xgendata file.)
try
    xgd = loadxgendata('ex_xgd_uc', mpc);
catch
    error(['Missing UC data file ex_xgd_uc. Provide a compatible xgendata UC file ', ...
           'or replace loadxgendata call with your dataset.']);
end

% Ensure xgd fields include all generators (including shedding gens)
ng = size(mpc.gen, 1);
fn = fieldnames(xgd);
for i = 1:numel(fn)
    v = xgd.(fn{i});
    if isnumeric(v) && size(v,1) == ng0
        xgd.(fn{i}) = [v; repmat(v(1,:), ng-ng0, 1)];
    end
end

% Make shedding generators always ON and flexible (no min up/down, no startup costs)
if isfield(xgd, 'CommitKey')
    % 1 means commitment/UC decision applies. Set to 0 for shedding gens (always available)
    xgd.CommitKey(shed_gen_idx) = 0;
end
if isfield(xgd, 'MinUp')
    xgd.MinUp(shed_gen_idx) = 0;
end
if isfield(xgd, 'MinDown')
    xgd.MinDown(shed_gen_idx) = 0;
end
if isfield(xgd, 'InitialState')
    xgd.InitialState(shed_gen_idx) = 1;
end

%% ===================== 5) Multi-period profiles (load) =====================
% Create a simple deterministic horizon if no external profile files are provided.
% Here: 24 periods with flat load (scale = 1.0).
nt = 24;
loadprof = struct( ...
    'type', 'mpcData', ...
    'table', CT_TBUS, ...
    'rows', (1:size(mpc.bus,1))', ...
    'col', PD, ...
    'chgtype', CT_REL, ...
    'values', [] );
loadprof.values = ones(nt, size(mpc.bus,1), 1);
profiles = loadprof;

%% ===================== 6) Add LODF-based N-1 security constraints (DC) =====================
% Build a base DC OPF model once (internal indexing) and add security constraints.
% NOTE: MOST will build its own multi-period model; we enforce N-1 constraints here
% at the network level by augmenting the base mpc with userfcn-style linear constraints
% inside MOST. For simplicity and completeness, we implement N-1 constraints through
% MOST's 'SecurityConstrained' interface is not assumed; instead we attach a userfcn
% that adds the same linear constraints to each period's DC model.

% Store security data needed by the userfcn
mpc.userdata = struct();
mpc.userdata.scopf = struct();

% Internal indexing for PTDF/LODF calculation
mpc_int = ext2int(mpc);
baseMVA = mpc_int.baseMVA;
bus = mpc_int.bus;
branch = mpc_int.branch;

in_service = (branch(:, BR_STATUS) == 1);
has_limit  = (branch(:, RATE_A) > 0);
cont_set   = find(in_service & has_limit);
if isempty(cont_set)
    error('Contingency set is empty (no in-service limited branches).');
end

% DC matrices
[~, Bf, ~, Pfinj] = makeBdc(baseMVA, bus, branch);
PTDF = makePTDF(baseMVA, bus, branch);
LODF = makeLODF(branch, PTDF);
rateA = branch(:, RATE_A);
constrain_lines = find(in_service & has_limit);

mpc.userdata.scopf.Bf = Bf;
mpc.userdata.scopf.Pfinj = Pfinj;
mpc.userdata.scopf.LODF = LODF;
mpc.userdata.scopf.rateA = rateA;
mpc.userdata.scopf.cont_set = cont_set;
mpc.userdata.scopf.constrain_lines = constrain_lines;

% Register a MOST user function to add constraints each period
mpc = add_userfcn(mpc, 'formulation', @userfcn_add_n1_lodf_constraints, mpc.userdata.scopf);

%% ===================== 7) Build MOST data model & solve =====================
mdi = loadmd(mpc, nt, xgd, [], [], profiles);
mdo = most(mdi, mpopt);

if verbose
    most_summary(mdo);
end

% Basic extraction of results
if isfield(mdo, 'results') && isfield(mdo.results, 'success')
    if ~mdo.results.success
        error('MOST SCUC did not solve successfully.');
    end
end

fprintf('\n=== Multi-period DC-SCUC with N-1 constraints and load shedding completed ===\n');


%% ========================================================================
%% Userfcn: add N-1 LODF-based constraints to each DC OPF model in MOST
function om = userfcn_add_n1_lodf_constraints(om, mpopt, args)
    define_constants;

    sc = args; % security data

    % Only meaningful for DC formulations with Va variables
    if ~isfield(om.var.idx, 'i1') || ~isfield(om.var.idx.i1, 'Va')
        return;
    end

    nv = om.var.N;
    iVa1 = om.var.idx.i1.Va;
    iVaN = om.var.idx.iN.Va;

    Bf = sc.Bf;
    Pfinj = sc.Pfinj;
    LODF = sc.LODF;
    rateA = sc.rateA;
    cont_set = sc.cont_set;
    constrain_lines = sc.constrain_lines;

    nb = size(Bf, 2);
    nl = size(Bf, 1);

    nc = length(cont_set);
    nL = length(constrain_lines);
    nRows = 2 * nL * nc;

    A = spalloc(nRows, nv, 2 * nL * nc * nb);
    l = -inf(nRows, 1);
    u =  inf(nRows, 1);

    row = 0;
    for kk = 1:nc
        k = cont_set(kk);
        lodf_col = LODF(:, k);      % nl x 1
        Bf_row_k = Bf(k, :);        % 1 x nb
        Pk = Pfinj(k);

        Bf_k = Bf + lodf_col * Bf_row_k;
        Pf_k = Pfinj + lodf_col * Pk;

        for ii = 1:nL
            ell = constrain_lines(ii);
            limit = rateA(ell);

            aVa = Bf_k(ell, :);
            cst = Pf_k(ell);

            row = row + 1;
            A(row, iVa1:iVaN) = aVa;
            u(row) = limit - cst;

            row = row + 1;
            A(row, iVa1:iVaN) = -aVa;
            u(row) = limit + cst;
        end
    end

    if row ~= nRows
        error('N-1 constraint row mismatch (row=%d, expected=%d).', row, nRows);
    end

    om.add_lin_constraint('N1_branch_limits_LODF', A, l, u);
end
